module.exports = /*#__PURE__*/JSON.parse('{"Textiles":{"SDG_1":{"Circular":{"Awareness":"Map waste textiles or post-consumer materials available locally; identify informal or low-income community actors (collectors, repairers) who could participate in reuse and upcycling.","Developing":"Formalize partnerships with cooperatives or social enterprises for textile collection, sorting, and remanufacturing; monitor social and circular indicators (jobs created, tonnes reused).","Leading":"Scale inclusive upcycling hubs employing vulnerable groups; publish verified social and material-reuse outcomes; replicate models in new regions."},"Environmental":{"Awareness":"Assess occupational climate-risk exposure (heat stress, flooding, vector-borne disease); map vulnerable worker groups and local adaptation needs.","Developing":"Implement workplace cooling, water access, early-warning systems, and emergency plans; incorporate adaptation actions in EHS procedures and training.","Leading":"Regularly evaluate climate-risk indicators and health outcomes; publish resilience KPIs; collaborate with suppliers to replicate heat-safety measures in value chains."},"Economic":{"Awareness":"Benchmark wages against statutory minimums and credible living-wage estimates; identify gaps for vulnerable or contract workers.","Developing":"Adopt and disclose a formal living-wage policy; include living-wage clauses in supplier codes; monitor pay equity across gender and job levels.","Leading":"Publicly report wage ratios, living-wage coverage, and progress; collaborate with industry peers to raise wage floors across the sector."},"Social":{"Awareness":"Evaluate workers’ access to financial tools and vulnerabilities (indebtedness, lack of savings); identify relevant partners (credit unions, NGOs, digital-finance providers).","Developing":"Introduce on-site financial-literacy sessions, voluntary savings accounts, and access to fair-cost micro-credit or insurance; monitor participation and impacts.","Leading":"Integrate financial-well-being KPIs (e.g., % employees with savings accounts, reduction in payday-loan usage); scale programs through local partnerships."}},"SDG_2":{"Circular":{"Awareness":"Identify opportunities to substitute conventional mono-crop fibers (e.g., cotton) with agricultural residues and diverse plant fibers such as banana, hemp, or pineapple. Assess potential biodiversity benefits and local availability.","Developing":"Pilot product lines using diverse agricultural by-products; establish traceability for fiber origins; evaluate life-cycle impacts and farmer benefits.","Leading":"Scale production using regenerative, biodiversity-friendly fiber systems; publish biodiversity and livelihood outcomes from agricultural by-product sourcing."},"Environmental":{"Awareness":"Map agricultural inputs and identify ecosystems under stress; evaluate certification options (e.g., organic, regenerative, Rainforest Alliance, or Fairtrade).","Developing":"Adopt and verify sustainable agriculture standards across supply chains; integrate regenerative principles (cover cropping, minimal tillage, soil organic matter improvement).","Leading":"Co-develop regenerative-agriculture pilots with suppliers and farmers; measure ecosystem recovery and GHG reduction; report results via GRI and science-based targets."},"Economic":{"Awareness":"Identify existing suppliers’ scale and ownership type (smallholder, cooperative); analyze procurement concentration and local development impact.","Developing":"Source from verified smallholder cooperatives; offer long-term contracts or prepayment models; build local capacity for sustainable fiber cultivation.","Leading":"Report smallholder sourcing share (% of procurement); provide technical and financial support for productivity and resilience; co-create inclusive circular value chains."},"Social":{"Awareness":"Assess employee food access, dietary diversity, and affordability; evaluate workplace nutrition options and local food security context.","Developing":"Provide healthy canteen meals or food vouchers; integrate nutrition education into wellness programs; measure participation and satisfaction.","Leading":"Implement verified workplace-nutrition certification or SDG-aligned employee wellness benchmarks; disclose food security and nutrition performance publicly."}},"SDG_3":{"Circular":{"Awareness":"Map existing recycled/upcycled inputs, identify potential contaminants (e.g., PFAS, azo dyes, heavy metals), and review globally recognized safety certifications for textiles.","Developing":"Require chemical testing for all recycled/upcycled fibers; adopt supplier verification procedures; ensure compliance with recognized safety standards (e.g., OEKO-TEX, ZDHC MRSL).","Leading":"Set validated targets for certified-safe circular inputs; conduct third-party audits; publicly disclose toxic-free recycled-material performance."},"Environmental":{"Awareness":"Identify hazardous chemicals in processes, review regulatory lists, and map toxic hotspots.","Developing":"Adopt safer alternatives; phase out PFAS, chlorinated solvents, azo dyes, etc.; expand chemical inventories and conduct risk assessments.","Leading":"Implement a zero-toxic chemical strategy; publish chemical-reduction KPIs; certify facilities through ZDHC or OEKO-TEX STeP."},"Economic":{"Awareness":"Evaluate existing occupational health services (OHS) for both direct and contracted workers; assess absenteeism, ergonomic risks, and chronic-disease factors.","Developing":"Establish formal OHS programs, including regular check-ups, screening, ergonomics assessments, and preventive interventions; track improvement in productivity metrics.","Leading":"Achieve universal OHS coverage; integrate health indicators into productivity dashboards; publicly report on health outcomes and ROI."},"Social":{"Awareness":"Identify stressors and psychosocial risks; map availability of mental health services, workload practices, and work–life balance gaps.","Developing":"Introduce Employee Assistance Programs (EAPs), counseling services, burnout-prevention programs, and flexible work schemes (remote, flex-time, reduced hours).","Leading":"Integrate mental health into HR strategy; report well-being KPIs (stress reduction, satisfaction, retention); evaluate managers on well-being leadership competencies."}},"SDG_4":{"Circular":{"Awareness":"Assess current staff understanding of circularity and waste reduction; identify knowledge gaps in textile recycling, upcycling, and design for reuse.","Developing":"Create structured learning modules on circular textile systems; integrate life-cycle thinking, material selection, and waste prevention into technical and design roles.","Leading":"Establish accredited internal “Circular Skills” programs; share outcomes (trained staff, design improvements, waste reduction) in sustainability reporting."},"Environmental":{"Awareness":"Identify sustainability-related training gaps; include core topics like energy, water, waste, and chemicals management in onboarding.","Developing":"Embed sustainability learning in all job functions and performance reviews; track participation and effectiveness of training modules.","Leading":"Offer accredited sustainability certifications or micro-credentials; publicly report employee-training hours and outcomes in ESG reports."},"Economic":{"Awareness":"Conduct a workforce-skills gap assessment; identify critical technical, digital, and green skills relevant to current and future business competitiveness.","Developing":"Fund continuous-learning and certification opportunities (e.g., digital, sustainability, eco-design); establish mentoring or apprenticeship programs.","Leading":"Link upskilling programs with innovation outcomes and performance incentives; report % of employees trained and business impact metrics."},"Social":{"Awareness":"Assess representation gaps (gender, youth, disability, migrant status) in training and promotion; set inclusion objectives in HR and CSR policies.","Developing":"Create targeted education programs for marginalized groups (e.g., women in technical roles, youth apprenticeships, training for persons with disabilities).","Leading":"Track and publicly disclose participation and promotion rates for marginalized employees; partner with NGOs and education providers to scale inclusion programs."}},"SDG_5":{"Circular":{"Awareness":"Map women’s representation in all circular initiatives (eco-design, recycling, take-back, circular business models, innovation teams) and compare with overall workforce and leadership composition. Integrate gender equality into your circular strategy (targets, roles, KPIs).","Developing":"Set minimum gender-balance objectives for circular taskforces and steering groups; establish leadership and technical training pathways for women in circular design, recycling, and innovation roles; track promotion rates of women into circular-economy positions.","Leading":"Formally commit (e.g. WEPs signatory) to gender-balanced governance of circular initiatives; disclose gender-disaggregated data on participation and leadership in circular projects and set public targets for women’s leadership across the circular value chain."},"Environmental":{"Awareness":"Review OSH policies and risk assessments for gender bias (PPE fit, ergonomic design, exposure types, shift patterns, reproductive health risks). Collect sex-disaggregated injury, illness, and near-miss data.","Developing":"Adapt OSH measures to gender-specific needs (PPE sizing, workstation design, lifting and repetitive-task limits, pregnancy/breastfeeding protections); ensure women’s participation in OSH committees and incident investigations.","Leading":"Mainstream gender into OSH management systems and audits; publish gender-disaggregated OSH indicators and case studies of risk reduction; align with ILO guidance and WHO healthy-workplace principles."},"Economic":{"Awareness":"Map current policies on parental leave, family leave, flexible working, and childcare support; compare against ILO standards and identify gender gaps in uptake and career progression.","Developing":"Introduce or enhance paid parental leave (for all genders), family-care leave, flexible hours/remote work, and childcare support (on-site facilities, subsidies or partnerships). Track usage by gender and contract type.","Leading":"Align company policy with ILO C156 principles; ensure equal access to flexible work and leave for all genders; report on family-friendly benefits and their impact on retention, promotion, and pay equity."},"Social":{"Awareness":"Review existing codes of conduct, grievance mechanisms, and HR policies against ILO C190 benchmarks; identify whether gender-based violence and harassment are explicitly covered and understood by workers.","Developing":"Adopt and communicate a zero-tolerance policy for violence, harassment, and discrimination; create multiple confidential reporting channels (hotlines, ombudsperson, digital tools); ensure protection from retaliation and clear investigation procedures.","Leading":"Integrate C190 principles into enterprise agreements and supplier codes; train all managers and workers regularly; publish data on incidents and corrective actions (in line with GRI 406-1) while safeguarding confidentiality; involve women workers and unions in design and review of policies."}},"SDG_6":{"Circular":{"Awareness":"Map water use across processes (spinning, dyeing, finishing, washing); quantify baseline withdrawals, consumption, and discharge; identify hotspots where closed-loop or low-liquor technologies could be introduced.","Developing":"Introduce water-efficient machinery (low-liquor dyeing, counter-current rinsing, condensate reuse) and internal re-use loops for suitable streams; embed water efficiency objectives and monitoring in a formal management system.","Leading":"Certify a water-efficiency management system (e.g., ISO 46001), integrate water-footprint results into design and process choices, and disclose water efficiency KPIs (litres/kg textile, % water reused) in sustainability reports."},"Environmental":{"Awareness":"Identify all wastewater streams (process, cooling, sanitary); characterize key pollutants (colour, COD/BOD, salts, chemicals) and applicable regulatory or buyer requirements; map current treatment capacity and gaps.","Developing":"Install and operate appropriate treatment (screening, equalization, biological treatment, filtration, sludge handling); monitor effluent quality (pH, COD/BOD, TSS, key chemicals) and maintain records to demonstrate compliance and continual improvement.","Leading":"Align treatment with best available techniques; explore water reclamation for process reuse; conduct water-footprint assessments for products and sites, and publicly disclose performance through CEO Water Mandate or similar platforms."},"Economic":{"Awareness":"Quantify the full cost of water (abstraction, treatment, energy for pumping/heating, chemicals, discharge fees) and link it to production volumes; identify cost-saving opportunities from efficiency and reuse.","Developing":"Integrate water-efficiency targets into financial planning and capital budgeting (e.g., ROI for water-saving equipment, payback on reuse systems); monitor reduction in water and wastewater costs as part of resource-efficiency KPIs.","Leading":"Use standardized water-efficiency and water-footprint approaches to support scenario analysis (e.g., rising tariffs, scarcity risk); disclose cost savings and risk-reduction benefits of water projects, and reinvest part of savings in further efficiency or community WASH."},"Social":{"Awareness":"Assess WASH (Water, Sanitation and Hygiene) conditions at all sites (including supplier facilities where possible): availability, quality, privacy, gender-appropriateness, and accessibility of drinking water, toilets, and handwashing stations.","Developing":"Implement company standards for WASH provision (minimum ratios of toilets to workers, separate facilities for women and men, menstrual-hygiene facilities, safe drinking water, handwashing with soap); train supervisors and workers on hygiene practices and monitor compliance.","Leading":"Commit publicly to universal, gender-responsive WASH for all workers across operations and priority suppliers; integrate WASH indicators into social audits and ESG reporting, and partner with local stakeholders to extend WASH access to surrounding communities."}},"SDG_7":{"Circular":{"Awareness":"Identify where energy is lost (e.g., heat from dyeing/finishing machines, steam systems, compressed air leaks, exhaust air); assess technical feasibility of heat recovery and internal reuse loops.","Developing":"Install heat-recovery systems (e.g., dyeing-machine heat exchangers, boiler economizers), reuse condensate in pre-heating, and integrate thermal-loop monitoring into an energy-management system.","Leading":"Set circular energy targets (% recovered energy), link them to ISO 50001 certification, and publicly disclose energy-recovery performance and reductions in primary energy demand."},"Environmental":{"Awareness":"Quantify current energy mix (grid electricity, fuels, heat, steam) and identify hotspots for renewable-energy substitution; analyze regulatory/market incentives or PPAs (power purchase agreements).","Developing":"Implement renewable-energy procurement (PPAs, green tariffs), install on-site solar/biomass/biogas heat systems, and replace fossil fuels in boilers where possible.","Leading":"Commit to science-based decarbonization targets; achieve majority-renewable electricity or heat; certify renewable sourcing and publicly disclose progress annually."},"Economic":{"Awareness":"Conduct an energy audit to identify outdated or inefficient machinery (motors, boilers, compressors, dyeing machines) and evaluate the financial impact of energy inefficiency (fuel, electricity, downtime costs).","Developing":"Invest in high-efficiency motors, variable-frequency drives, optimized boilers, LED lighting, and smart automation; include energy criteria in procurement; track ROI on efficiency investments.","Leading":"Integrate energy efficiency into core business strategy; report cost savings, avoided emissions, and productivity gains; require suppliers to adopt similar systems."},"Social":{"Awareness":"Assess current employee understanding of energy practices, identify high-impact behaviors (machine shutdown, leaks, temperature settings), and map training gaps across roles.","Developing":"Develop structured employee training on efficient equipment operation, shutdown procedures, leak reporting, and renewable-energy use. Launch awareness campaigns and operator-level certifications.","Leading":"Establish a “Clean Energy Champions” program; incentive teams for energy-saving innovations; publicly disclose training hours and employee engagement outcomes tied to energy KPIs."}},"SDG_8":{"Circular":{"Awareness":"Map current end-of-life pathways (landfill, recycling, reuse); assess feasibility of rental, resale, repair, upcycling, or take-back models; identify consumer demand and barriers.","Developing":"Pilot circular business models: in-store repair services, clothing rental programs, resale marketplaces, or take-back incentives; measure returns, customer engagement, and waste reduction.","Leading":"Scale circular business models across product categories; integrate reverse logistics; disclose circular revenue share and textile-waste prevention outcomes; collaborate with municipalities or NGOs on large-scale collection."},"Environmental":{"Awareness":"Evaluate production inefficiencies in energy use, water, chemicals, and waste; conduct an environmental performance assessment aligned with ISO and GRI frameworks.","Developing":"Introduce low-impact production technologies (e.g., digital printing, enzymatic processing, low-liquor dyeing, renewable heat systems), track reductions in energy, water, chemicals, and emissions.","Leading":"Commit to science-based sustainability targets; integrate eco-efficiency into long-term planning; publicly report environmental improvements using globally recognized disclosure standards."},"Economic":{"Awareness":"Analyze current product portfolio for sustainability performance; identify opportunities for bio-based fibers, recycled-content textiles, or low-impact material innovations.","Developing":"Invest in R&D to develop low-impact, circular, or recyclable textile products; establish innovation partnerships (suppliers, research institutes, start-ups); track sales of sustainable products and associated savings.","Leading":"Scale sustainable product lines; link performance metrics (e.g., % sustainable revenue) to corporate strategy; disclose innovation outcomes in ESG reporting."},"Social":{"Awareness":"Identify youth employment gaps, barriers to accessing textile jobs, and existing training programs; benchmark against ILO youth-employment guidelines.","Developing":"Launch targeted apprenticeship, vocational training, and upskilling programs for young workers—including technical, digital, and green skills—while promoting pay equity and transparent career pathways.","Leading":"Institutionalize youth employment pipelines, partner with technical schools, ensure equal pay and gender equality in training access, and publish gender- and age-disaggregated training/employment data."}},"SDG_9":{"Circular":{"Awareness":"Identify current design practices and production flows; map material inputs, waste streams, and recyclability; assess gaps in circular design (durability, repairability, recyclability, mono-materials).","Developing":"Integrate circular design criteria into product development (design for longevity, disassembly, mono-materiality, recycled content); set measurable goals and update sourcing specifications and technical packs.","Leading":"Apply advanced circular-design frameworks across all collections; track circularity indicators (recycled content %, recyclability score, product-life extension metrics); publicly report progress."},"Environmental":{"Awareness":"Assess current manufacturing infrastructure (boilers, dyeing machines, compressors, HVAC, wastewater treatment); quantify energy, water, and emissions hotspots using recognized environmental-performance frameworks.","Developing":"Upgrade machinery (low-liquor dyeing, digital printing, high-efficiency motors, solar thermal, modern boilers); integrate energy/water monitoring systems; optimize production layouts to reduce losses.","Leading":"Commit to best-available technology (BAT) upgrades; link infrastructure investments to science-based targets; publish verified environmental performance improvements annually."},"Economic":{"Awareness":"Evaluate current R&D spending; identify innovation gaps in materials, processes, digitalization, circularity, and chemical substitution; benchmark against industry innovation trends.","Developing":"Fund R&D in sustainable fibers (recycled, bio-based), low-impact dyeing/finishing, digital manufacturing, and recycling technologies; establish partnerships with research institutes and startups.","Leading":"Scale commercially viable innovations; integrate sustainability innovation KPIs into corporate performance; publish R&D outcomes tied to emissions, water, and materials impact reductions."},"Social":{"Awareness":"Identify competency gaps linked to new infrastructure (automation, digital tools, upgraded machinery); assess training needs for technicians, operators, and maintenance staff.","Developing":"Provide structured training on advanced machinery, automation, digital tools, and sustainability-driven technologies; integrate safety, efficiency, and maintenance modules.","Leading":"Create long-term career pathways linked to advanced infrastructure; certify operators; publish outcomes (training hours, productivity gains, reduced incidents); ensure equal access for women and young workers."}},"SDG_10":{"Circular":{"Awareness":"Map who participates in circular activities (repair, sorting, take-back, upcycling). Identify participation gaps among women, migrants, youth, low-income workers, and persons with disabilities.","Developing":"Include underrepresented groups in circular business operations (sorting centers, textile repair, community recycling hubs). Create partnerships with cooperatives or social enterprises employing vulnerable workers.","Leading":"Formalize inclusive procurement, track inclusion outcomes (jobs created, % diverse suppliers), and publicly disclose progress through sustainability reporting."},"Environmental":{"Awareness":"Review how sustainability decisions are made and who participates; identify representation gaps (role, age, gender, ethnicity).","Developing":"Create diverse, cross-role sustainability committees; provide equal participation opportunities in environmental programs (recycling teams, energy champions, waste audits).","Leading":"Institutionalize inclusive participation through transparent nomination processes and track representation in sustainability governance; disclose participation data."},"Economic":{"Awareness":"Review compensation structures; identify disparities by gender, age, job category, or minority-status; map wage practices against living-wage benchmarks.","Developing":"Establish transparent salary bands, standardized promotion criteria, and clear bonus policies; ensure equal pay reviews and corrective measures.","Leading":"Publish pay-equity achievements; conduct independent audits; integrate equitable compensation into HR policies, board oversight, and supplier requirements."},"Social":{"Awareness":"Assess current diversity, representation, and inclusion culture; identify barriers for minority groups; benchmark against UN and ILO guidelines.","Developing":"Develop internal diversity programs, anti-bias training, cultural-awareness workshops, mentorship networks, and inclusive leadership training.","Leading":"Integrate inclusion indicators into HR policies, set representation goals, publish diversity data, and collaborate with communities or NGOs promoting social inclusion."}},"SDG_11":{"Circular":{"Awareness":"Map textile waste streams across operations and retail; identify existing municipal, SME, and NGO partners involved in collection, sorting, and recycling; assess volumes and current end-of-life routes (landfill, incineration, export).","Developing":"Co-design take-back, reuse, and recycling schemes with municipalities, social enterprises, and SMEs (e.g., urban collection points, sorting hubs, repair/upcycling workshops). Track quantities collected, reused, and recycled, and integrate waste-prevention targets into company strategy.","Leading":"Scale city-level circular textile systems (e.g., regional hubs for collection and mechanical/chemical recycling), publish case studies with city or NGO partners, and disclose performance (tonnes diverted, % textile waste reused/recycled, local jobs created)."},"Environmental":{"Awareness":"Identify major emission sources (boilers, dryers, generators, process vents, transport) and pollutants (PM, NOx, SO₂, VOCs); compare measured or estimated emissions against WHO Air Quality Guidelines and national standards; map nearby communities potentially affected.","Developing":"Install and operate appropriate emission-control technologies (e.g., filters, scrubbers, low-NOx burners), shift to cleaner fuels, and enforce good maintenance practices; monitor stack and fugitive emissions and report internally.","Leading":"Align site emission-reduction plans with WHO guideline values and local urban air-quality strategies; publish emissions data (e.g., NOx, SO₂, PM) and engage with local authorities and communities on air-quality improvements."},"Economic":{"Awareness":"Identify existing and potential urban partners (tailors, repair cafés, upcycling studios, social enterprises) that can extend product life, repair garments, or repurpose textile offcuts; assess barriers (finance, skills, logistics, contracts).","Developing":"Establish commercial or partnership contracts with local micro-enterprises for repair, alteration, remanufacturing, and upcycling; co-design business models (e.g., repair vouchers, branded upcycled capsules) and measure jobs created and local income generated.","Leading":"Create structured support programmes (micro-finance access, technical training, equipment donations, joint branding) for urban micro-enterprises; report on urban–rural value-chain linkages (e.g., rural fiber, urban repair, reuse) and social outcomes."},"Social":{"Awareness":"Assess workers’ living and commuting conditions (cost, time, safety), and on-site services (canteens, lockers, rest areas); identify groups most affected by housing and transport challenges (e.g., low-wage, shift workers, women, migrants).","Developing":"Introduce or strengthen measures such as subsidized or healthy canteen meals, safe company transport or transport allowances, flexible hours/shift design, and—where relevant—support for safe and decent housing (dormitories standards, housing allowances, or partnerships).","Leading":"Embed quality-of-life measures into corporate policy (e.g., minimum standards for canteens, transport safety, support for commuting and childcare); track and report their impact on retention, absenteeism, and employee satisfaction, and engage with city authorities on mobility and housing solutions."}},"SDG_12":{"Circular":{"Awareness":"Map material flows across product lines and determine current levels of pre-consumer and post-consumer recycled content. Identify gaps compared with sector benchmarks and assess technical limits for integrating recycled fibers.","Developing":"Set targets for increasing recycled content; include recycled-material specifications in procurement; engage recyclers and suppliers to improve supply consistency; test durability and safety of recycled fibers.","Leading":"Integrate recycled-content targets into product development across all lines; certify recycled inputs (e.g., GRS/RCS); disclose progress transparently in sustainability reporting."},"Environmental":{"Awareness":"Conduct environmental audits to identify hotspots in water, energy, and chemical use; document current consumption intensities and compare against international best practices.","Developing":"Implement efficiency improvements: low-liquor dyeing, digital printing, heat recovery, renewable thermal energy, waste-minimization techniques, and material substitution. Track reductions through KPIs.","Leading":"Adopt best-available technologies (BAT), set science-based reduction targets, and integrate resource-efficiency indicators into annual sustainability reports."},"Economic":{"Awareness":"Identify material sustainability topics (resource efficiency, waste reduction, emissions, water use) and determine which KPIs have financial relevance.","Developing":"Integrate sustainability KPIs into financial forecasts, risk assessments, and investment decisions; align reporting with GRI, TCFD, or integrated-reporting frameworks.","Leading":"Publish integrated sustainability-financial reports; link performance to executive incentives; apply scenario analysis and disclose resource-efficiency cost savings."},"Social":{"Awareness":"Assess current levels of sustainability understanding among employees and consumers; identify knowledge gaps related to textile impacts, circularity, and responsible purchasing.","Developing":"Deliver staff training on sustainable production, circularity, chemicals management, and efficient resource use; provide consumer education through labeling, workshops, digital platforms, and transparent product information.","Leading":"Integrate sustainability education into corporate culture; run public communication campaigns; collaborate with NGOs, schools, and retailers to promote responsible consumption; disclose impact of awareness programs."}},"SDG_13":{"Circular":{"Awareness":"Assess product-level greenhouse gas emissions using life-cycle thinking (raw material → manufacturing → use → end-of-life), focusing on design parameters such as fiber type, recycled content, durability, and recyclability.","Developing":"Quantify product carbon footprints (PCF) for key items and use results to redesign toward lower-impact options: higher recycled content, lower-impact fibers, design for longevity, repairability, and end-of-life recovery (recycling/composting).","Leading":"Set product-level climate targets (e.g., % reduction in PCF for core lines; % of products designed for recyclability and reuse); disclose methodology and results in sustainability reporting and engage suppliers and brands on low-carbon design standards."},"Environmental":{"Awareness":"Establish a corporate greenhouse gas inventory covering Scope 1, 2, and relevant Scope 3 emissions (materials, logistics, use phase, end-of-life) as a baseline for reduction.","Developing":"Set time-bound emission-reduction targets and implement decarbonization levers: energy efficiency, renewable energy, lower-impact materials, process optimization, and logistics improvements.","Leading":"Align targets with recognized climate frameworks and disclose progress annually (e.g., through CDP, GRI, or TCFD-aligned reports), including Scope 3 and value-chain engagement."},"Economic":{"Awareness":"Identify physical (heat, floods, water stress) and transition (policy, market, technology, reputation) climate risks along the textile value chain; map potential opportunities (circular models, low-carbon materials, energy savings).","Developing":"Conduct scenario analyses and integrate climate risks and opportunities into strategic planning, capital expenditure, and product portfolio decisions (e.g., shifting towards circular, low-carbon textiles).","Leading":"Align climate risk management with board-level oversight and remuneration; disclose climate-related financial information in line with TCFD (or successor IFRS S2) and show how climate scenarios influence investments, sourcing, and circular business models."},"Social":{"Awareness":"Assess current understanding of climate risks and textile-sector impacts among employees; identify key audiences (designers, sourcing teams, production managers, logistics, sales) and their training needs.","Developing":"Create structured climate-training modules (e-learning, workshops) explaining climate science, textile-sector emissions, circular design, and mitigation options; link training to concrete workplace actions (energy-saving campaigns, low-impact design briefs, supplier engagement).","Leading":"Institutionalize climate education as part of onboarding and continuous learning; create employee climate-action groups, recognize contributions (e.g., internal awards, innovation challenges), and report climate training coverage and impacts in sustainability disclosures."}},"SDG_14":{"Circular":{"Awareness":"Identify pollution pathways from textile products and processes (microfibers, synthetics, dyes, finishes). Assess current material composition (synthetic vs. natural fibers), propensity for microfiber release, and available circular alternatives.","Developing":"Introduce circular design strategies such as recycled synthetics, reduced synthetic blends, low-shedding yarn technologies, and microfiber-capture systems in production and laundry testing. Require suppliers to meet fiber-shedding performance criteria.","Leading":"Set measurable microfiber-reduction targets; adopt preferred circular fibers; publicly disclose fiber-shedding performance and circular-material progress; collaborate with research institutes on ocean-pollution reduction."},"Environmental":{"Awareness":"Conduct wastewater baseline assessments for COD/BOD, dyes, metals, microfibers, and chemical additives. Compare with international discharge limits.","Developing":"Implement filtration, biological treatment, chemical substitution, microfiber filters, and Zero-Liquid-Discharge (ZLD) or partial-recycling systems. Require suppliers to comply with the company’s wastewater standards.","Leading":"Achieve discharge quality far below legal thresholds; partner with municipalities for water-body restoration; publicly disclose wastewater KPIs under GRI 303."},"Economic":{"Awareness":"Identify pollution-related costs: chemical overuse, wastewater fees, sludge disposal, fines, energy for aeration, and water losses.","Developing":"Introduce cleaner-production measures that reduce chemical consumption and sludge volume; adopt water-recycling technologies that lower operating costs; track efficiency and payback.","Leading":"Integrate pollution-reduction KPIs into financial planning; disclose water-efficiency savings; reinvest gains into ocean-health initiatives or higher efficiency technologies."},"Social":{"Awareness":"Identify knowledge gaps among employees and suppliers regarding wastewater impacts, chemical pollution, and marine ecology; map local water stakeholders (NGOs, municipal operators, river-basins).","Developing":"Deliver training on pollution prevention, responsible chemical use, microfiber reduction, and impacts of ocean acidification. Engage suppliers through workshops and shared audits.","Leading":"Establish employee “water stewardship teams”; collaborate with NGOs on river cleanups and awareness campaigns; report participation and impact metrics (e.g., number of employees trained)."}},"SDG_15":{"Circular":{"Awareness":"Map all fiber inputs (cotton, MMCFs, wool, synthetics, alternative fibers) and quantify the share of virgin land-based fibers vs. recycled or waste-based inputs. Identify land-use hotspots in the value chain and link them to fiber choices.","Developing":"Adopt circular fiber strategies (recycled cotton, recycled synthetics, textile-to-textile recycling, agricultural residues) and set targets to replace virgin land-based inputs with secondary or waste-based sources, while checking for overall biodiversity and land impacts.","Leading":"Link fiber strategy explicitly to land-footprint reductions; set and disclose KPIs such as % of fiber from recycled or waste-based sources and land-footprint-per-garment; align with global biodiversity/land goals (Kunming–Montreal Framework)."},"Environmental":{"Awareness":"Map where key raw materials come from (countries, biomes, high-biodiversity areas) and identify deforestation, habitat-conversion and land-degradation risks associated with those regions and crops (e.g., cotton, MMCFs, leather, rubber).","Developing":"Embed no-deforestation / no-conversion, high conservation value (HCV), and high carbon stock (HCS) criteria in sourcing policies; require traceability and certification (e.g., FSC, PEFC, organic, regenerative schemes) for forest- or land-based fibers.","Leading":"Align sourcing with the Kunming–Montreal Global Biodiversity Framework and emerging deforestation-free regulations; publicly report biodiversity impacts and mitigation using GRI 101/304 disclosures."},"Economic":{"Awareness":"Screen the business for nature-related dependencies (e.g., water, soil fertility, forest ecosystems, pollination) and impacts (deforestation, habitat loss, pollution), and link them to financial risks (supply disruption, regulation, reputation, cost increases).","Developing":"Use a structured process (e.g., TNFD LEAP: Locate–Evaluate–Assess–Prepare) to assess nature-related risks and opportunities by geography, commodity, and supplier; integrate outputs into investment screening, sourcing strategy, and scenario analysis.","Leading":"Set biodiversity-related targets and integrate them into financial planning (CAPEX, OPEX, M&A, sourcing contracts); disclose nature-related risks and management responses in line with TNFD and GRI 101, and align with the Kunming–Montreal Global Biodiversity Framework."},"Social":{"Awareness":"Identify sourcing regions where local communities, Indigenous Peoples or smallholders manage forests, grasslands or agricultural land; assess how company sourcing impacts local ecosystems and community rights.","Developing":"Co-design biodiversity and land-management initiatives with communities (e.g., agroforestry, restoration, diversified cropping, community monitoring, benefit-sharing) linked to company sourcing programs; ensure FPIC where applicable.","Leading":"Establish long-term partnerships and benefit-sharing agreements with communities; support community-led monitoring and restoration; publicly report on community engagement, biodiversity outcomes, and social benefits using GRI community and biodiversity disclosures."}},"SDG_16":{"Circular":{"Awareness":"Map supply chain tiers and identify transparency gaps. Begin collecting basic supplier information (origin, certifications, material flow). Align initial practices with OECD traceability expectations","Developing":"Require suppliers to disclose traceability data (material origins, recycled content, certifications).Conduct formal third-party assessments or audits. Integrate traceability requirements into supplier contracts and onboarding.","Leading":"Deploy digital traceability tools (blockchain, traceability platforms). Support supplier training on transparency and circular sourcing. Publicly report traceability results linked to circular material flows."},"Environmental":{"Awareness":"Identify environmental impacts (energy, water, chemicals, emissions). Start basic tracking using core GRI environmental indicators. Begin aligning practices with ISO 14001 fundamentals.","Developing":"Implement a formal Environmental Management System (EMS) based on ISO 14001.  Set measurable targets on key environmental aspects. Introduce annual reporting with internal audits.","Leading":"Achieve certified ISO 14001 or comparable EMS certification. Integrate EMS into supplier requirements. Publish audited environmental performance reports transparently."},"Economic":{"Awareness":"Identify corruption risks in procurement, payments, and supplier relations. Provide basic anti-corruption training to staff and procurement teams. Align policies with UN Global Compact principles.","Developing":"Implement a formal anti-corruption policy and whistleblowing channel. Conduct due diligence on suppliers and financial partners.  Introduce clear procurement controls (documentation, segregation of duties).","Leading":"Apply third-party anti-corruption audits. Publicly report anti-corruption performance via GRI. Participate in international anti-corruption initiatives and sector pacts."},"Social":{"Awareness":"Draft and communicate a basic non-discrimination and equal opportunity policy. Train managers on inclusive behavior and legal obligations. Start collecting diversity data (age, gender, nationality where legally allowed).","Developing":"Implement grievance mechanisms and reporting channels. Integrate non-discrimination requirements into hiring, promotion, and supplier policies. Conduct periodic bias and equality assessments.","Leading":"Publish diversity and inclusion KPIs transparently (GRI-aligned). Participate in global equality initiatives. Provide leadership training on inclusion and embed policies across all regions."}},"SDG_17":{"Circular":{"Awareness":"Map suppliers and identify circular design gaps. Start basic material-flow tracking aligned with GRI 301. Join an introductory circular platform (e.g., EMF resources hub).","Developing":"Form partnerships with suppliers or universities to pilot recycled fibers or circular material loops. Apply ISO 59010 guidance to redesign products for durability, reuse, and repair. Actively participate in multi-stakeholder circularity networks.","Leading":"Co-develop closed-loop textile systems with global partners. Publish circular performance transparently (GRI-aligned). Support supplier capacity-building in developing countries on circular design."},"Environmental":{"Awareness":"Identify existing environmental technologies used across operations. Benchmark against UNEP sustainable textile practices. Begin tracking environmental performance using GRI 302–305 categories.","Developing":"Provide suppliers with training on clean production (energy, water, chemicals). Engage in regional or international projects that support technology transfer (UNFCCC CTCN).  Share best practices with partners in developing regions.","Leading":"Co-finance or donate environmental technology packages (e.g., wastewater recycling, low-impact dyeing).  Lead open-access environmental training programs for global partners.  Participate in UN-supported demonstration projects for sustainable textile technologies."},"Economic":{"Awareness":"Document all current sustainability-related financial flows.  Identify opportunities to access SDG-aligned external funding. Begin basic GRI 201 economic disclosures","Developing":"Build partnerships to secure external financing (grants, blended finance, investors). Co-invest with private or public entities in circular or sustainable textile pilots. Apply SDG Impact Standards when preparing financial proposals.","Leading":"Mobilize multi-stakeholder funds for large-scale sustainable textile initiatives.  Issue SDG-linked financing tools (green bonds, sustainability-linked loans).  Serve as a case study for OECD or UN financing platforms."},"Social":{"Awareness":"Map existing networks and partnerships. Align internal practices with OECD due diligence expectations. Join introductory webinars or basic knowledge-sharing platforms (UNIDO, ILO).","Developing":"Join recognized sectoral partnerships (ILO Better Work, UN Fashion Charter). Share case studies on circularity, worker welfare, and environmental improvements. Build partnerships with regional universities, research institutes, or NGOs.","Leading":"Lead international working groups or industry alliances. Provide supplier training programs in developing regions. Develop open-access guidance materials used by the wider textile sector."}}},"Fertilizers":{"SDG_1":{"Circular":{"Awareness":"Communicate the climate mitigation benefits, specifically the reduction of methane from landfills and avoided emissions from synthetic fertilizer production.","Developing":"Formalize the initiative by disclosing it under relevant sustainability standards. Report on waste diverted (GRI 306) and positive local economic impacts (GRI 413).","Leading":"Engage with local and indigenous knowledge systems to improve the adoption and effectiveness of the bio-fertilizer program, strengthening social cohesion."},"Environmental":{"Awareness":"Conduct a Climate Vulnerability and Human Rights Assessment for your operations and supply chain, focusing on identifying \\"vulnerable workers\\" (e.g., migrant, outdoor, low-income, pregnant, or workers with disabilities).","Developing":"Develop and implement a Heat Stress Management Plan based on recognized health thresholds. This includes providing rest breaks, shade, water, and acclimatization schedules for outdoor and indoor workers without cooling.","Leading":".Integrate climate resilience metrics into executive and management scorecards, linking the protection of vulnerable workers to overall business continuity and social license to operate."},"Economic":{"Awareness":"Conduct a Living Wage Gap Analysis for all employee categories and key supplier regions. Compare actual wages against credible, benchmarked living wage estimates, not just legal minimum wages.","Developing":"Establish a formal corporate commitment and policy to achieve a living wage for all direct employees and integrate this requirement into supplier codes of conduct.  Implement a time-bound, costed action plan that includes direct employees and key suppliers, developed through social dialogue.","Leading":".Publicly disclose progress, integrate metrics into executive incentives, and champion industry-wide collaboration to elevate standards beyond the company\'s direct operations."},"Social":{"Awareness":"Conduct a confidential needs assessment to identify specific financial literacy gaps and barriers to accessing financial services and Benchmark current company practices against investor expectations regarding social factors and employee well-being.","Developing":"Develop and deliver tailored financial-literacy programs with credible local partners, ensuring accessibility through local languages, paid-time participation, and inclusive design for women, migrant workers, and other marginalized groups.","Leading":"Integrate financial-inclusion KPIs such as workforce completion rates for financial-literacy training into management scorecards and executive incentives. Publicly disclose participation rates, demographic data, and key outcomes (e.g., increased savings, small business creation) in annual sustainability reports."}},"SDG_2":{"Circular":{"Awareness":"Map regional organic waste streams (e.g., from food processing, agriculture, wastewater treatment) to identify reliable, scalable sources of feedstock, assessing their volume, composition, and logistics.","Developing":"Establish a rigorous quality assurance and sourcing protocol for incoming waste streams to ensure product safety, traceability, and consistent nutrient content, in line with regulatory requirements.","Leading":"Publicly disclose the percentage of products derived from recovered nutrients and the associated environmental benefits (e.g., tonnes of waste diverted, CO2e emissions avoided) in mainstream financial and sustainability reports."},"Environmental":{"Awareness":"Conduct a supply chain mapping and risk assessment to identify primary sourcing regions and evaluate their current levels of crop diversity versus monoculture practices. Use the LEAP approach to Locate your interface with nature and Evaluate dependencies and impacts on agrobiodiversity.","Developing":"Establish a sustainable sourcing policy with specific criteria for agrobiodiversity, including preferential purchasing from farms that maintain diverse crop varieties and traditional seeds.","Leading":"Create premium pricing mechanisms and long-term contracts that provide financial incentives for suppliers who excel in conserving genetic diversity and traditional crop varieties."},"Economic":{"Awareness":"Conduct a comprehensive market analysis in partnership with local agricultural cooperatives to identify the specific financial, logistical, and knowledge barriers that prevent smallholder farmers from accessing and adopting bio-based fertilizers.","Developing":"Establish accessible financing mechanisms, such as pay-after-harvest schemes, micro-leasing, or digital microloans, integrated with farmer training on the economic benefits of bio-based fertilizers to improve affordability and demonstrate return on investment.","Leading":"Integrate smallholder market access into the core business strategy by linking executive and managerial KPIs to targets for smallholder farmer inclusion and the percentage of revenue generated from these channels."},"Social":{"Awareness":"Conduct an anonymous employee survey and review of workplace food environments to assess food insecurity, dietary needs, affordability barriers, and employee preferences for nutritious options.","Developing":"Develop and implement a formal Workplace Food and Nutrition Policy that commits to providing a minimum percentage of healthy, culturally appropriate meal options, using guidelines from health authorities.","Leading":"Achieve external certification for workplace food services (e.g., from national healthy canteen initiatives) and integrate employee nutrition and food security metrics into executive sustainability scorecards and bonus structures."}},"SDG_3":{"Circular":{"Awareness":"Conduct a comprehensive risk assessment to identify and categorize potential contaminants (e.g., heavy metals, pathogens, persistent organic pollutants) in all incoming streams of recovered bio-materials based on their source and processing history.","Developing":"Implement a standardized and documented quality assurance protocol for all recovered bio-materials, including mandatory batch testing for key contaminants against recognized safety standards (e.g., EU FPR, WHO guidelines).","Leading":"Integrate long-term environmental and human health monitoring into your product lifecycle assessment, tracking the impact of your recovered materials on soil health and ecosystem biodiversity over time."},"Environmental":{"Awareness":"Conduct a comprehensive process audit and emissions inventory to identify and quantify all sources of toxic emissions (e.g., ammonia, nitrogen oxides, sulfur oxides, heavy metal dust, fluorides) and hazardous by-products (e.g., gypsum pond sludge, acidic waste streams) across all manufacturing sites.","Developing":"Invest in and implement BAT (Best Available Techniques) for pollution abatement, such as advanced scrubbers for acid gases, catalytic reduction systems for NOx, dust filtration systems, and process optimization software to minimize raw material waste and energy consumption.","Leading":"Integrate \\"green chemistry\\" and \\"benign-by-design\\" principles into R&D, focusing on developing next-generation fertilizer products and manufacturing processes that inherently generate fewer hazardous substances."},"Economic":{"Awareness":"Conduct a comprehensive review of occupational health data (e.g., injury rates, absenteeism, staff turnover) and employee health risk factors through surveys and focus groups to identify the most significant health burdens impacting workforce productivity.","Developing":"Establish and fund an on-site or near-site occupational health service that provides regular, mandatory health check-ups, risk-specific screenings (e.g., for exposure to dust, chemicals, noise), and access to a qualified occupational health professional.","Leading":"Link executive and managerial performance scorecards and incentives to the improvement of key workforce health metrics, directly aligning leadership priorities with employee well-being outcomes."},"Social":{"Awareness":"Conduct anonymous employee surveys and focus groups to assess mental health stigma, identify key stressors (workload, work-life balance), and gauge the demand for different types of flexible work arrangements.","Developing":"Implement a formal, multi-faceted Mental Health at Work Policy that includes confidential access to counseling (EAP), mental health first-aid training for managers, and awareness campaigns to reduce stigma.","Leading":"Integrate manager performance on team well-being and psychological safety into leadership competency models and performance reviews, holding leaders accountable for fostering a supportive culture."}},"SDG_4":{"Circular":{"Awareness":"Conduct a skills gap analysis to identify specific training needs across relevant departments (e.g., R&D, production, quality control, sales, and marketing) regarding circular nutrient principles, recovery technologies, and product safety protocols.","Developing":"Implement mandatory, role-specific technical training. For production staff, this covers operating recovery technologies (e.g., composters, digesters); for quality control, it focuses on testing for contaminants; for sales teams, it involves communicating safety and benefits to farmers.","Leading":"Partner with technical colleges, universities, and industry associations to co-develop certified training curricula for \\"Circular Nutrient Management,\\" helping to build a skilled talent pipeline for the entire sector."},"Environmental":{"Awareness":"Conduct a training needs assessment to identify specific environmental knowledge gaps across different roles (e.g., executives, operations, procurement, sales) and map them to the company\'s most material environmental impacts (e.g., climate, water, waste).","Developing":"Develop and mandate a core environmental sustainability module for all new hires during onboarding, covering the company\'s key policies, impacts, goals (e.g., Net Zero, Zero Waste), and how every employee can contribute.","Leading":"Integrate sustainability knowledge and behavioral competencies into formal performance reviews, promotion criteria, and incentive structures for all management levels, making it a non-negotiable component of career advancement."},"Economic":{"Awareness":"Benchmark current investment in employee development (as a percentage of payroll or revenue) against industry peers and best practices to establish a baseline and build a financial case for increased funding.","Developing":"Develop and deliver in-house training academies or digital learning platforms in partnership with accredited institutions to provide scalable, role-specific training (e.g., in data analytics, sustainable procurement, circular design) that leads to internal or external micro-credentials.","Leading":"Integrate a commitment to continuous upskilling into leadership competency models and manager performance goals, holding them accountable for the career development and skill advancement of their team members."},"Social":{"Awareness":"Conduct a comprehensive, anonymized audit of training participation, completion rates, and promotion outcomes, disaggregated by gender, race, ethnicity, disability status, and other relevant demographics to identify existing disparities.","Developing":"Ensure all skill development programs are accessible by design, offering flexible schedules, providing materials in multiple formats, covering childcare costs, and ensuring physical and digital accessibility for employees with disabilities.","Leading":"Publicly disclose disaggregated data on training participation and career progression rates for underrepresented groups, and set ambitious, time-bound public targets for closing identified gaps."}},"SDG_5":{"Circular":{"Awareness":"Conduct a gender-disaggregated audit of the company\'s R&D, innovation, and product development teams to establish a baseline for women\'s participation at all levels (e.g., researchers, project leads, senior decision-makers).","Developing":"Establish and fund a dedicated mentorship and sponsorship program that pairs women in junior R&D roles with senior leaders (both male and female) who can provide career guidance, advocate for their inclusion in high-visibility projects, and support their advancement.","Leading":"Link executive and R&D leadership bonuses to the achievement of gender diversity and inclusion targets within innovation teams, making equitable participation a non-negotiable component of strategic performance."},"Environmental":{"Awareness":"Hold confidential consultations and focus groups with female employees to understand their specific perspectives, concerns, and experiences regarding environmental risks in the workplace","Developing":"Ensure gender balance and active participation of women in environmental monitoring teams, safety committees, and emergency response drills to incorporate diverse perspectives in risk identification and protocol development.","Leading":"Appoint and empower a senior-level \\"Gender and Sustainability Champion\\" responsible for overseeing the integration of gender considerations across all environmental management and OSH practices, with a direct reporting line to the executive team."},"Economic":{"Awareness":"Benchmark the company\'s current family leave, childcare support, and flexible work policies against national laws, industry leaders, and international labor standards to identify gaps and opportunities for improvement.","Developing":"Establish a formal, non-transferable, and fully paid parental leave policy for all parents (primary and secondary caregivers) that meets or exceeds ILO standards, with a clear guarantee of job protection upon return.","Leading":"Champion a \\"Care-Forward\\" business culture by becoming a public advocate for public policies that support childcare and paid family leave, and by collaborating with industry peers to set a new, higher standard for family-friendly workplaces."},"Social":{"Awareness":"Benchmark the company\'s current anti-harassment policy and reporting procedures against the specific requirements of ILO C190 and other international best practices to identify critical gaps in definitions, scope, and protection for reporters.","Developing":"Develop and communicate a clear, comprehensive policy that explicitly prohibits violence and harassment, defines prohibited behaviors (including psychological and online harassment), and protects all workers, including those in third-party employment relationships.","Leading":"Publicly disclose, in line with privacy protections, aggregated data on the number of harassment reports received, investigation outcomes, and disciplinary actions taken, to demonstrate transparency and build trust in the system."}},"SDG_6":{"Circular":{"Awareness":"Conduct a comprehensive water balance and wastewater audit to map all water inputs, uses, and outputs, quantifying the volume and quality of all wastewater streams generated.","Developing":"Develop and install the necessary dual plumbing and distribution infrastructure to safely transport treated wastewater to points of reuse within the facility (e.g., for cooling towers, boiler feed, or non-potable process water).","Leading":"Set ambitious, time-bound targets to achieve \\"Zero Liquid Discharge\\" (ZLD) or to maximize the circularity of water use by reusing a majority of treated wastewater, integrating these targets into corporate water stewardship strategy."},"Environmental":{"Awareness":"Conduct a water risk assessment to identify areas of the business most vulnerable to water scarcity, rising water costs, and reputational risks, prioritizing these sites for efficiency investments.","Developing":"Implement operational best practices for water management, including regular preventative maintenance to fix leaks, employee training on water conservation, and process optimization to minimize water use (e.g., counter-current washing).","Leading":"Integrate water efficiency as a key performance indicator (KPI) for site managers and executives, linking a portion of their compensation to the achievement of water reduction targets."},"Economic":{"Awareness":"Conduct a comprehensive water cost audit to map all direct and indirect costs associated with water, including freshwater purchase, energy for pumping/heating/treating, wastewater discharge fees, and chemical usage for water treatment.","Developing":"Implement wastewater recovery and reuse projects to directly reduce freshwater purchase costs and wastewater discharge fees, treating wastewater as a resource for non-potable applications","Leading":"Publicly disclose the financial savings achieved from water efficiency and reuse initiatives, linking them to key performance indicators (KPIs) like reduced cost of goods sold (COGS) or improved operating margin."},"Social":{"Awareness":"Conduct a collaborative community needs assessment with local authorities and community leaders to understand gaps in WASH infrastructure and services in communities surrounding company operations, prioritizing the most vulnerable.","Developing":"Upgrade and maintain all workplace WASH facilities to meet or exceed ILO/WHO standards, ensuring they are gender-segregated, accessible, secure, private, and consistently supplied with soap, potable water, and menstrual hygiene facilities.","Leading":"Integrate WASH performance into the key performance indicators (KPIs) for site and community relations managers, linking their performance evaluations to the maintenance of internal standards and positive community health outcomes."}},"SDG_7":{"Circular":{"Awareness":"Benchmark current energy recovery rates against industry best practices and assess the regulatory and financial landscape for energy recovery technologies (e.g., grants, carbon credits) in your region.","Developing":"Establish a monitoring and maintenance system to track the performance of energy recovery installations, ensuring they operate at optimal efficiency and deliver the expected energy and cost savings.","Leading":"Champion industrial symbiosis by exploring opportunities to supply excess recovered energy (e.g., surplus biogas, steam) to neighboring industries, positioning the company as a clean energy hub and creating a new revenue stream."},"Environmental":{"Awareness":"Assess the technical and economic feasibility of renewable energy sources (e.g., on-site solar, wind, procurement of green power from utilities, Power Purchase Agreements - PPAs) for your specific locations and operational needs.","Developing":"Develop a phased Renewable Energy Transition Plan with clear short-term and long-term targets, starting with \\"low-hanging fruit\\" like installing on-site solar PV for office/warehouse electricity before addressing high-temperature industrial process heat.","Leading":"Integrate renewable energy criteria into all capital expenditure (CapEx) decisions for new facilities and major upgrades, making \\"renewable-first\\" the default standard for all future operations."},"Economic":{"Awareness":"Benchmark current energy intensity (GJ/ton of product) against industry averages and Best Available Techniques (BAT) to identify performance gaps and prioritize investments in the areas with the highest potential for savings.","Developing":"Establish an Energy Management System (EnMS) to systematically track, manage, and continuously improve energy performance, integrating energy efficiency into daily operational procedures and maintenance schedules.","Leading":"Champion industrial energy efficiency by sharing best practices with suppliers and peers, collaborating on R&D for next-generation low-energy production processes, and advocating for policies that support energy efficiency investments."},"Social":{"Awareness":"Develop and deliver foundational awareness training for all relevant employees on the business case, operational principles, and environmental benefits of the clean energy technologies being deployed.","Developing":"Implement mandatory, hands-on technical training and certification programs for operational and maintenance staff, developed in partnership with equipment vendors or technical colleges, to ensure the safe and efficient operation of clean energy assets.","Leading":"Integrate clean energy competencies and innovation goals into performance development plans and leadership competency models, making the management of energy assets a core skill for technical career progression."}},"SDG_8":{"Circular":{"Awareness":"Conduct a comprehensive material flow analysis to map and quantify all nutrient inputs (virgin vs. recovered) and waste outputs, identifying key opportunities for closing nutrient loops within the company\'s operations and local economy.","Developing":"Invest in or partner with technology providers and MSMEs to develop and scale processes for recovering high-quality nutrients from organic waste streams (e.g., composting, anaerobic digestion, struvite precipitation).","Leading":"Integrate circular innovation and the development of local supplier partnerships into the company\'s R&D strategy and executive performance metrics, making the transition to a circular nutrient model a core strategic pillar."},"Environmental":{"Awareness":"Conduct a Life Cycle Assessment (LCA) to quantify the environmental footprint (e.g., GHG emissions, water pollution, energy use) of conventional fertilizer products and identify \\"hotspots\\" where green technologies would have the greatest impact.","Developing":"Systematically replace a portion of virgin mineral feedstocks (e.g., phosphate rock) with recovered nutrients from certified organic waste streams, establishing quality and safety protocols for these alternative inputs.","Leading":"Integrate \\"Environmental Impact per Ton of Product\\" as a core operational and strategic KPI, and link executive incentives to the successful development and market penetration of green fertilizer products."},"Economic":{"Awareness":"Analyze the potential for new job creation in the company\'s sustainability roadmap, linking specific initiatives (e.g., installing solar power, launching a recycled product line) to projected new roles in installation, operation, and maintenance.","Developing":"Prioritize sustainable business expansions and process changes that have a high potential for local job creation, such as establishing a facility for recycling organic waste into bio-fertilizers or offering product-as-a-service models that require maintenance and refurbishment roles.","Leading":"Champion green job creation by collaborating with industry associations to develop sector-wide green job classifications, advocating for supportive education and training policies, and sharing best practices on a just transition with peers and suppliers."},"Social":{"Awareness":"Conduct a gender representation audit across all levels of the organization, from entry-level to the board, to establish a baseline for women\'s participation in leadership and decision-making roles.","Developing":"Establish a clear, transparent, and bias-free compensation framework that defines pay ranges for all roles based on objective criteria like skills, experience, and responsibility, not negotiation history.","Leading":"Link executive and senior management bonuses directly to the achievement of measurable gender equality KPIs, including the closure of the pay gap and increased representation of women in leadership."}},"SDG_9":{"Circular":{"Awareness":"Conduct a comprehensive material and energy input/output analysis to identify underutilized resources, by-products, and waste streams (e.g., waste heat, CO2, organic residues, process water) that could be valuable to other local industries.","Developing":"Establish pilot partnerships with one or two local businesses to test the feasibility of exchanging resources (e.g., providing organic waste to a biogas plant, using another factory\'s waste heat, supplying gypsum as a construction material).","Leading":"Champion the development of \\"Eco-Industrial Parks\\" or regional symbiosis networks by collaborating with municipal governments, industry associations, and research institutions to create enabling policies, shared infrastructure, and innovation hubs."},"Environmental":{"Awareness":"Conduct a comprehensive technology and infrastructure audit to benchmark current production assets against international standards for energy efficiency, pollution control, and resource consumption (e.g., water, raw materials).","Developing":"Establish a rigorous Operations & Maintenance (O&M) schedule and use digital monitoring systems to ensure all upgraded infrastructure continues to operate at peak efficiency and delivers the expected environmental and financial returns.","Leading":"Integrate \\"Green Performance\\" criteria—such as energy efficiency, emissions levels, and circular design—into all capital expenditure (CapEx) decisions and corporate financing frameworks, making sustainable infrastructure the default for all new investments."},"Economic":{"Awareness":"Conduct a strategic analysis of the sustainable fertilizer market to identify high-potential innovation areas (e.g., bio-based fertilizers, nutrient-use efficiency enhancers, green ammonia production) and assess the competitive landscape.","Developing":"Form strategic innovation partnerships with public research institutions, agricultural universities, and technology startups to co-develop and de-risk new technologies, leveraging external expertise and shared funding.","Leading":"Integrate \\"Sustainable Product Portfolio\\" growth as a key performance indicator for the R&D and executive leadership teams, linking incentives to the successful commercialization of innovative, sustainable fertilizer solutions."},"Social":{"Awareness":"Do a quick training-needs scan with employee input — a simple questionnaire + focus groups to identify skills gaps and employees’ barriers to participation (time, language, digital access). Use findings to prioritise low-effort, high-impact modules (e.g., waste sorting, energy-saving operating procedures).","Developing":"Embed participatory design & workers’ voice — set up regular worker feedback loops (surveys, toolbox talks) to adapt training content and capture obstacles. Offer transition support (reskilling for changing roles)","Leading":"Create career pathways & certified upskilling — map how green competencies lead to progression (operator → specialist → team lead). Offer accredited training (external certificates) and time-bound targets for internal promotions tied to green skill attainment."}},"SDG_10":{"Circular":{"Awareness":"Test a small, low-cost pilot that supplies mixed batches of recycled/bio-based fertilizer to 50–200 smallholders and run short, practical demos on application rates and safety. Use pilots to collect farmer feedback (price, efficacy, handling) before scaling.","Developing":"Work with cooperatives or micro-distributors to bundle small, affordable packs of bio-based fertilizers and establish collection/return points for organic feedstock—reduce unit costs and logistical barriers for remote smallholders. Consider small credit or voucher pilots to lower upfront cost.","Leading":"Commit to procurement targets for recycled/bio-based inputs sourced through smallholder partnerships (e.g., X% by year Y). Combine with blended finance or off-taker guarantees to de-risk supply aggregation and enable predictable demand for small producers."},"Environmental":{"Awareness":"share a one-page poster (visual + multiple languages) explaining how any employee can join a green suggestion, pilot, or rota (and what support/recognition they’ll receive). This lowers access barriers for marginalized staff","Developing":"Form small mixed teams (operators, maintenance, admin) that rotate membership every 3–6 months so employees from diverse backgrounds gain hands-on roles in waste reduction, nutrient recovery pilots, or biodiversity actions. Track representation and outcomes.","Leading":"Set measurable targets for diverse employee participation in improvement initiatives (e.g., % of improvement leads from under-represented groups) and include in sustainability/HR reporting (use GRI/CDP disclosure approaches)"},"Economic":{"Awareness":"invite representative employees (including temporary, seasonal and migrant workers) for 1–2 hour sessions to surface experiences with benefits access, bonus allocation and informal pay practices; document barriers (e.g., hours, language, informal allocation). Use findings to prioritise measures.","Developing":"Define clear, documented eligibility rules for benefits and incentive schemes (including part-time, agency, seasonal staff where feasible) and apply pro-rata or equivalent access to reduce exclusion. Pilot small corrective top-ups where data show large gaps.","Leading":"Require third-party suppliers/aggregators (e.g., for raw materials or seasonal labour) to meet minimum wage/benefit standards and include worker representatives in compensation review panels to ensure marginalized voices shape incentive design. Use OECD-FAO guidance for agri supply chains to structure due diligence."},"Social":{"Awareness":"Pair each new or marginalized employee with an experienced peer for 4–8 weeks to ease cultural onboarding and encourage participation in trainings/events.","Developing":"partner with local VET/FAO or ILO training providers to offer micro-credentials (e.g., cultural competency, anti-bias, leadership) and guarantee paid work time so marginalized staff can participate.","Leading":"align company D&I policy to ISO 30415 (roles, accountability, risk assessment) and create a cross-functional Inclusion Board (with worker representatives) that approves training, events and mentor programmes"}},"SDG_11":{"Circular":{"Awareness":"Map all packaging types used (bags, sacks, bulk containers, liners), note composition (virgin plastic vs recycled, reusable vs single‑use) and identify 1‑2 quick switches (e.g., sacks with 30 % recycled content or reusable bulk liners). Use this audit as an awareness tool with the team.","Developing":"Engage your packaging provider to redesign sacks or big‑bags with: (a) higher recycled content, (b) design for recyclability (mono‐material, easy to separate), or (c) enable reuse/return of containers. Include packaging life‑cycle cost in supplier contract.","Leading":"Define KPIs such as % of packaging material that is recycled content, % packaging reusable, average packaging weight per tonne of product, and integrate these into procurement/supplier performance metrics."},"Environmental":{"Awareness":"Identify major waste streams in the production process (e.g., waste water, sludge, nutrient‐rich effluents, off‑spec product). Share the map in a short briefing with operators/maintenance so everyone understands where ‘leaks’ occur and where a closed‑loop could start.","Developing":"Select one by‑product (e.g., wastewater stream, sludge, off‑spec granulate) and implement a small‑scale recovery loop (e.g., capture phosphorus/nitrogen, treat the effluent, reuse in fertilizer mix or process water). Measure the amount recovered, waste reduced and quality of reused product.","Leading":"Define KPIs (e.g., tonnes of nutrient recovered, % reduction in effluent discharge, litres of water reused per tonne product). Incorporate circular design criteria into new equipment/process upgrades (design for reuse, internal loops)."},"Economic":{"Awareness":"Use a simple audit to establish current consumption metrics: e.g., m³ water/tonne, kWh/tonne, kg raw material per tonne output. Share results with production teams to raise awareness of cost and waste opportunities.","Developing":"Define and measure KPIs such as kWh/tonne, m³ water/tonne, kg raw feed/tonne. Set targets, assign ownership (e.g., production manager), and tie part of performance bonus to improvements.","Leading":"Make resource/utility efficiency a strategic pillar: include in capital investment decision‑making, set corporate targets for resource reduction per tonne, embed into sustainability report and link to long‑term economic sustainability and competitiveness."},"Social":{"Awareness":"Conduct a short, anonymous survey asking employees about commute times, safety concerns, transportation costs, and local housing issues. Share results internally to highlight gaps and raise awareness among management.","Developing":"Set up subsidized cafeterias, meal vouchers, or partnerships with local vendors to provide nutritious meals at lower cost, improving employee health and convenience.","Leading":"Track employee satisfaction with housing, commute, and workplace facilities; incorporate KPIs into annual HR and sustainability reporting; link improvements to talent retention and economic performance."}},"SDG_12":{"Circular":{"Awareness":"Conduct a facility-wide waste audit and material flow analysis to categorize and quantify all waste streams and identify recoverable nutrient content.","Developing":"Establish clear standard operating procedures (SOPs) and quality controls for handling and processing recovered nutrients to ensure they meet safety and quality standards for reuse.","Leading":"Integrate real-time waste and nutrient tracking data into executive dashboards and operational management, linking performance to strategic goals and continuous improvement cycles."},"Environmental":{"Awareness":"Map products containing nutrients (N, P, K), their typical application rates, and likely runoff pathways. Share simplified results with production and R&D teams to raise awareness of eutrophication risks.","Developing":"Pilot projects measuring nutrient leaching or surface runoff from product usage under controlled conditions; use findings to adjust product formulations or application guidance.","Leading":"Use LCA tools to quantify freshwater and marine eutrophication potential of all fertilizer products; include mitigation measures (e.g., slow-release N/P, bio-based additives) in standard product development."},"Economic":{"Awareness":"Conduct a comprehensive market analysis to identify customer demand, price sensitivity, and competitive landscape for bio-based slow-release fertilizers in key regions.","Developing":"Allocate R&D and capital expenditure specifically for developing and scaling production of certified bio-based slow-release fertilizers, focusing on cost-effective and locally sourced feedstocks.","Leading":"Integrate the bio-based fertilizer strategy into the core business plan, linking executive incentives to market share targets and forming strategic alliances with distributors and large agricultural cooperatives to ensure widespread adoption."},"Social":{"Awareness":"Use simple multilingual visuals to reinforce safe practices (e.g., protective equipment, correct stacking, spill response) and make employees aware of social responsibility in safe chemical management.","Developing":"Develop training modules specific to each job role covering storage, handling, transport and application of fertilizers/chemicals; include short assessments or practical exercises to ensure employees from all backgrounds understand and can apply practices.","Leading":"Conduct periodic audit of training records, language/shift/contract‑type inclusion, incident reduction and include findings in sustainability or social disclosures."}},"SDG_13":{"Circular":{"Awareness":"Map all organic waste and nutrient-rich effluent streams from operations to identify the highest-potential sources for valorization and the associated emission reduction from avoiding landfill methane and reducing virgin resource use.","Developing":"Develop and launch certified low-carbon fertilizer products that clearly communicate their reduced GHG footprint due to circular sourcing, targeting customers and markets with climate commitments.","Leading":"Champion the integration of circular nutrient management into national climate strategies (NDCs) by sharing data, participating in policy dialogues, and advocating for incentives that reward carbon-smart fertilizer production."},"Environmental":{"Awareness":"Provide operations, logistics and maintenance teams with an introductory workshop on the relevance of energy consumption, transport fuel use, and emissions reduction in the fertilizer supply chain. Encourage staff to propose 2–3 “quick wins”","Developing":"Use your baseline to set SMART goals (e.g., X% reduction in energy per tonne product, Y% of transport fuel from renewable sources, Z% reduction in CO₂eq by year Y). Embed into budgeting and capital planning to ensure projects are recognised.","Leading":"Incorporate emissions and climate resilience metrics (e.g., carbon‑intensity per tonne product, % renewable energy share, reduction in transport emissions) into annual sustainability reports, aligned with frameworks (e.g., ISO 14064, GRI, CDP). Use this to enhance investor & stakeholder confidence and internal accountability."},"Economic":{"Awareness":"Conduct a climate risk and opportunity assessment using the TCFD framework to identify transition risks (e.g., carbon pricing, shifts in demand) and physical risks (e.g., drought, flooding) that could impact financial performance.","Developing":"Allocate a defined percentage of the R&D budget to the development of low-carbon and climate-resilient products, such as enhanced-efficiency fertilizers or green ammonia, linking product development to climate strategy.","Leading":"Integrate climate performance metrics (e.g., revenue from low-carbon products, progress on decarbonization) into executive compensation schemes and long-term corporate strategy, making climate accountability a board-level priority."},"Social":{"Awareness":"Provide short, bite‑sized content (e‑mail links, posters, videos) covering climate change risks and relevance to production, procurement and operations. Use multilingual formats if your workforce is diverse.","Developing":"For each function (e.g., production, logistics, sales, maintenance) design short training (2‑3 hours) on how climate change impacts the value chain (e.g., raw‑material scarcity, extreme weather, supply chain disruption) and what mitigation/adaptation actions staff in that role can take.","Leading":"Make climate‑adaptation/mitigation training part of the company’s standard induction, annual refresher programmes and manager competency requirements. Link participation and knowledge uptake to performance reviews and leadership development."}},"SDG_14":{"Circular":{"Awareness":"Deliver introductory sessions for employees on how nutrient runoff affects marine ecosystems (eutrophication, dead zones) and how circular practices like nutrient recovery, recycling, and reuse can mitigate these impacts.","Developing":"Introduce redesigned production and packaging processes to reduce plastic and chemical leakage (e.g., returnable packaging, waste-to-resource loops). Ensure alignment with marine biodiversity protection objectives.","Leading":"Embed nutrient recovery, by-product valorization, and zero-leakage systems into long-term corporate planning. Monitor impacts specifically on marine ecosystems and publicly report reductions."},"Environmental":{"Awareness":"Benchmark current effluent quality against the EU\'s Water Framework Directive and other stringent regional standards to assess compliance risks and identify gaps in pollution control.","Developing":"Implement a robust water quality monitoring and management system with real-time sensors and regular laboratory testing to ensure continuous compliance with internal and external effluent standards","Leading":"Champion a \\"Zero Harmful Discharge\\" ambition by investing in circular nutrient recovery systems that treat wastewater as a resource, extracting nutrients for reuse in fertilizers and closing the loop to prevent marine pollution entirely."},"Economic":{"Awareness":"Conduct a basic internal assessment mapping how fertilizer nutrient losses contribute to marine pollution (eutrophication hotspots) and the potential economic benefits of innovations like slow-release or stabilized fertilizers.","Developing":"Collaborate with research organizations to co-develop or test nutrient-efficient fertilizers that reduce marine eutrophication while ensuring product performance, affordability, and market acceptance.","Leading":"Dedicate a portion of annual investment to scaling low-leaching formulations, recovering nutrients from waste streams, and redesigning products to outperform competitors in sustainability and cost efficiency."},"Social":{"Awareness":"Partner with a marine research institution to conduct a literature review and develop an internal briefing on the links between fertilizer-derived nitrogen runoff, coastal eutrophication, and ocean acidification.","Developing":"Co-fund and participate in a local or regional scientific monitoring program with research bodies to track nutrient levels in watersheds that lead to sensitive coastal areas.","Leading":"Establish and fund an \\"Ocean Health and Sustainable Agriculture\\" innovation prize or grant program for scientists and NGOs to develop new solutions for preventing nutrient runoff, positioning the company as a leader in the field."}},"SDG_15":{"Circular":{"Awareness":"Offer introductory staff training on how sourcing organic waste reduces land degradation, desertification, and virgin resource dependency.","Developing":"SMEs collaborate with local agricultural producers or biogas operators to begin sourcing manure, compost, and digestate to substitute part of the virgin raw materials.","Leading":"SMEs fully embed nutrient-loop sourcing (organic waste, manure, digestate) into procurement policies and long-term supply contracts, reducing dependence on virgin materials and decreasing land degradation impacts."},"Environmental":{"Awareness":"Conduct a comprehensive pre-mining baseline assessment of soil health, biodiversity, and hydrology at extraction sites to establish a scientific benchmark for post-mining restoration goals.","Developing":"Develop and implement a Mine Closure and Rehabilitation Plan that is integrated into the mining lifecycle from the outset, with dedicated financial provisioning (e.g., a rehabilitation bond or fund).","Leading":"Publicly disclose key performance indicators on rehabilitation, such as the percentage of disturbed land under active restoration and the hectares of land successfully rehabilitated to a pre-agreed productive or ecological state."},"Economic":{"Awareness":"Conduct a baseline review of financial allocations (R&D, operations, sourcing) to determine where biodiversity, soil restoration, or sustainable land-use investments are currently lacking.","Developing":"Assign small but targeted funds to pilot projects such as soil-rebuilding initiatives, landscape restoration, or biodiversity-friendly farming practices with upstream suppliers.","Leading":"Commit substantial financial resources to large-scale regenerative programs (e.g., cover cropping, erosion control, soil carbon enhancement) through partnerships with farmers and communities."},"Social":{"Awareness":"Develop and deliver mandatory foundational training for all R&D, production, and agronomic staff on the principles of soil health and the links between fertilizer use and ecosystem impacts (e.g., eutrophication, soil biodiversity loss).","Developing":"Create and disseminate detailed \\"Ecosystem Protection Guidelines\\" for internal production (to prevent pollution) and for sales agronomists (to advise farmers on application practices that minimize runoff and protect nearby wetlands and forests).","Leading":"Establish a certification or bonus incentive program for employees who demonstrate exceptional leadership in integrating ecosystem protection into their work, and partner with universities to develop a certified curriculum for \\"Sustainable Fertilizer Management.\\""}},"SDG_16":{"Circular":{"Awareness":"Begin by identifying all recycled inputs (e.g., compost, digestate, industrial by-products) and reviewing whether labeling, SDS, and communication meet minimum standards.","Developing":"Implement improved labeling that clearly states recycled material content, origin (e.g., manure, digestate, biomass ash), and safety handling details, supported by publicly available SDS.","Leading":"Offer customers real-time access to recovery method details, recycled-input percentages, and environmental profiles of fertilizer products."},"Environmental":{"Awareness":"Conduct a materiality assessment in accordance with GRI Standards to identify the most significant environmental, social, and governance (ESG) risks and impacts of your fertilizer production to determine what to disclose","Developing":"Publish an annual sustainability report aligned with GRI Standards that discloses the results of your risk assessments, and actively share this report with key stakeholders, including local communities, suppliers, and investors.","Leading":"Establish a multi-stakeholder advisory panel, including community representatives, NGOs, and academics, to review sustainability performance, validate assessment methodologies, and provide input on the company\'s long-term environmental strategy."},"Economic":{"Awareness":"Create a short, clear policy that defines acceptable and unacceptable practices related to supplier selection, purchasing, incentives, and subsidy use.","Developing":"Use due diligence checklists, conflict-of-interest declarations, and supplier background checks to ensure fairness in sourcing.","Leading":"Adopt digital procurement systems that track bids, pricing, and subsidy allocation, providing auditable trails and reducing human discretion."},"Social":{"Awareness":"Conduct confidential surveys and focus groups with employees, suppliers, and smallholder farmers to identify key sustainability concerns and gauge interest in participation mechanisms.","Developing":"Establish a formal \\"Sustainability Committee\\" or \\"Green Team\\" with rotating, elected representatives from different employee levels and departments to provide input on environmental policies and goals.","Leading":"Appoint a designated \\"Stakeholder Ombudsperson\\" and implement a transparent grievance mechanism that allows employees and value chain partners to raise sustainability concerns anonymously and without fear of reprisal."}},"SDG_17":{"Circular":{"Awareness":"Identify EU, national, and regional funding programs (e.g., Horizon Europe, EU Circular Economy programs, national bioeconomy funds) that the company could access for circular fertilizer technologies.","Developing":"Co-create small pilot projects on composting, nutrient recovery, or regenerative practices with actors in developing partner countries to access blended finance or development grants.","Leading":"Co-invest in large-scale circular fertilizer infrastructure with support from international financing institutions"},"Environmental":{"Awareness":"Conduct an internal audit to identify proprietary technologies, processes, or best practices in energy efficiency, nutrient recovery, or pollution prevention that could be valuable for partners in developing countries.","Developing":"Establish structured knowledge-sharing programs with suppliers or customers abroad. Offer training modules, virtual workshops, or exchange visits focused on environmentally sound fertilizer production methods.","Leading":"Provide licensing, open-access designs, or reduced-cost technology packages to partners in developing countries for low-carbon fertilizer production."},"Economic":{"Awareness":"Encourage SMEs to recognize simple sustainable practices (energy efficiency, waste reduction, optimized raw material use) that lead to cost savings, higher margins, and better cash flow, strengthening tax contributions and reinvestment capacity","Developing":"Report how sustainable operations improve profitability and cash flow, demonstrating increased tax contributions and reinvestment into local operations, reinforcing domestic economic impact.","Leading":"Invest in advanced circular fertilizer technologies (bio-based fertilizers, nutrient recovery, energy-efficient processes) to enhance long-term revenue stability, reduce operational costs, and strengthen contributions to national taxes and reinvestment."},"Social":{"Awareness":"Map potential public and private partners (e.g., national agricultural research institutes, technology startups, NGOs) to identify collaboration opportunities in areas like nutrient recovery, green ammonia, or soil health.","Developing":"Establish a formal partnership with a local agricultural university to create a training and internship program, building a pipeline of talent skilled in sustainable fertilizer use and production.","Leading":"Publicly champion the partnership model by publishing joint case studies and impact reports, and actively advocate for public policies that create a supportive environment for pre-competitive R&D collaborations in the agri-food sector."}}},"Packaging":{"SDG_1":{"Circular":{"Awareness":"Build awareness of the social benefits of reusable/recyclable packaging; collect data on packaging waste and local employment opportunities; identify community partnerships and value-chain gaps using GRI 306-3 and ISO 14001 references.","Developing":"Formalize circular packaging programmes employing local workers in collection, sorting, and reuse; set measurable targets (e.g., tonnes reused, number of local jobs created); integrate monitoring using life-cycle and social indicators.","Leading":"Communicate results (jobs created, packaging reuse rates); collaborate with municipalities, NGOs, and SMEs; replicate community-based circular models regionally."},"Environmental":{"Awareness":"Build awareness of heat and climate risks to factory workers; perform vulnerability assessments using ILO and UNDRR frameworks.","Developing":"Integrate resilience actions into OHS policies: improve ventilation, provide shaded rest areas, hydration, and emergency protocols; set and monitor performance targets.","Leading":"Publicly disclose climate-resilience measures and outcomes; collaborate with brands, unions, and local authorities to scale good practices."},"Economic":{"Awareness":"Map current wage levels and inclusion gaps; benchmark against local living-wage standards; raise awareness of inclusive hiring methods.","Developing":"Establish policies guaranteeing decent wages and inclusive recruitment; set measurable targets (e.g., % above minimum wage, % from disadvantaged backgrounds); implement audits and reporting.","Leading":"Communicate progress in social-impact reporting; engage in sectoral collaborations to scale fair-wage and inclusive-employment models."},"Social":{"Awareness":"Identify workers’ access gaps to banking, savings, and benefits; collect baseline data; reference financial inclusion standards.","Developing":"Formalize partnerships with financial institutions or NGOs; offer training and savings schemes; define participation and savings-growth targets; monitor impact.","Leading":"Communicate outcomes (training reach, improved savings, reduced debt); collaborate with governments and supply-chain partners to replicate inclusion programmes across regions"}},"SDG_2":{"Circular":{"Awareness":"Assess the origin and type of bio-based inputs used in packaging; distinguish between food-grade feedstocks and secondary biomass such as crop residues, forest by-products, or algae. Promote awareness of life-cycle impacts and competition with food systems using ISO 14040 and ISO 14044 (LCA)","Developing":"Adopt procurement policies prioritizing renewable, non-food and residual biomass feedstocks; integrate traceability of bio-based inputs through ISO 22095 (Chain of Custody) and disclose renewable-material share under GRI 301-1 and 301-2. Collaborate with suppliers to assess feedstock sustainability using FAO’s Sustainability Assessment of Food and Agriculture Systems (SAFA) framework.","Leading":"Invest in R&D for next-generation bio-materials derived from agricultural or forestry residues and industrial side streams. Publicly commit to sourcing only non-food, renewable, and regenerative feedstocks and report progress through transparent life-cycle indicators (ISO 14067, GRI 301)."},"Environmental":{"Awareness":"Identify all bio-based inputs in packaging and their geographic origin; assess exposure to biodiversity risks such as monoculture feedstocks or land-use change. Raise internal awareness using FAO’s State of the World’s Biodiversity for Food and Agriculture and ISO 14055 guidance on sustainable land management.","Developing":"Source bio-based raw materials from certified sustainable systems (e.g., FSC, PEFC, organic, or regenerative agriculture). Include biodiversity protection clauses in supplier codes and verify compliance through ISO 19011-based audits. Report sourcing volumes and certification coverage under GRI 304 (Biodiversity).","Leading":"Collaborate with producers to restore ecosystems and maintain genetic diversity of feedstocks; invest in regenerative agriculture projects that enhance soil health, pollinator habitats, and seed diversity. Publish impact metrics (hectares restored, biodiversity indicators improved) and align targets with the UN Decade on Ecosystem Restoration."},"Economic":{"Awareness":"Map current suppliers of bio-based or agricultural feedstocks and identify opportunities to engage small-scale or cooperative producers. Raise awareness of inclusive sourcing models and decent-work principles following ILO Recommendation 204 on the transition from informal to formal economy.","Developing":"Establish inclusive procurement criteria favoring cooperatives and smallholders certified under fair-trade or sustainable agriculture schemes (e.g., Fairtrade International, Rainforest Alliance). Monitor sourcing volumes and price premiums paid; disclose progress in supplier-development indicators under GRI 204-1.","Leading":"Co-create long-term partnerships with small-scale producers through capacity-building, microfinance, and technology transfer. Track income growth and productivity improvements, and report shared-value outcomes aligned with the UN Sustainable Food Systems Roadmap."},"Social":{"Awareness":"Assess employee nutritional needs and local food security conditions; promote awareness of healthy, balanced diets and sustainable nutrition using WHO dietary guidelines and FAO’s Sustainable Diets Framework.","Developing":"Introduce workplace programs providing nutritious meals, food vouchers, or partnerships with local suppliers of sustainable foods. Integrate nutrition awareness into occupational health and well-being policies and monitor participation rates.","Leading":"Implement comprehensive corporate nutrition strategies addressing food access, affordability, and education; measure health outcomes and employee satisfaction; share results in sustainability reports aligned with SDG 2 and GRI 401/403 indicators."}},"SDG_3":{"Circular":{"Awareness":"Identify where reused or recycled materials enter the company’s packaging system; raise awareness of potential health and environmental risks associated with contaminants in secondary materials. Map supplier practices using ISO 18602 and ISO 18604 standards, and promote understanding of safe recycling and reuse aligned with the Ellen MacArthur Foundation’s “Vision for a Circular Economy for Plastic Packaging.”","Developing":"Establish procedures to test and certify reused or recycled materials before use in packaging (e.g., migration, heavy metals, and NIAS testing for food-contact applications). Require supplier declarations of conformity and integrate verification steps in procurement and design processes using ISO 18604 and UNEP chemical safety guidance. Disclose data through GRI 301 (Materials) and GRI 306 (Waste).","Leading":"Implement third-party verification of recycled content safety and establish transparent specifications for material reuse in packaging. Collaborate with recyclers and suppliers to develop closed-loop systems ensuring traceability and safety. Communicate testing results and improvement actions in sustainability reports aligned with GRI 301 and ISO 18604."},"Environmental":{"Awareness":"Develop a chemical inventory and identify substances of concern across the packaging value chain (e.g., additives, inks, coatings). Align mapping with UNEP’s Global Framework on Chemicals and Ellen MacArthur Foundation’s commitment to eliminate hazardous substances from packaging systems.","Developing":"Create a restricted substances list aligned with international chemical safety standards; conduct safer alternatives assessments following OECD guidelines. Integrate chemical substitution into ISO 14001 environmental management systems and report progress through GRI 301 (Materials) and 306 (Waste).","Leading":"Adopt a time-bound strategy to phase out persistent and toxic substances such as PFAS; verify safer alternatives through testing and life-cycle assessments. Partner with suppliers and industry coalitions to “design out” chemical hazards in alignment with circular economy principles."},"Economic":{"Awareness":"Raise awareness among management and workers of the benefits of occupational health services and preventive health surveillance. Conduct a baseline assessment of workforce health coverage and workplace safety conditions in line with ILO Convention 161 and Recommendation 171.","Developing":"Allocate funding for periodic medical check-ups and targeted health promotion programs; apply the hierarchy of controls to minimize risks. Track absenteeism, incident rates, and health outcomes through an ISO 45001-aligned management system.","Leading":"Integrate occupational health surveillance with ergonomic, psychosocial, and preventive health programs. Monitor productivity and wellbeing indicators, disclose performance publicly, and benchmark progress against international OHS standards."},"Social":{"Awareness":"Build understanding of mental health as an organizational responsibility; identify psychosocial risk factors such as workload, harassment, and poor work-life balance. Promote awareness using WHO and ILO mental health guidance.","Developing":"Implement psychosocial risk management under ISO 45003; provide confidential employee assistance programs (EAP) and train managers in supportive leadership. Introduce flexible working arrangements to support well-being and inclusion.","Leading":"Integrate mental health support into company-wide OHS and HR policies; set measurable targets (e.g., service uptake, stress reduction, retention rates). Publicly report outcomes under GRI 403 and 401, and share best practices across the industry."}},"SDG_4":{"Circular":{"Awareness":"Map roles that influence packaging across the value chain (design, procurement, operations, reverse logistics) and identify skill gaps in circular concepts (reuse models, design for recyclability, reverse flows). Build a training baseline aligned to circular economy principles and basic eco-design.","Developing":"Create role-specific curricula (e.g., designers on design-for-reuse/recyclability; operations on return/refill handling; procurement on circular specifications). Track participation and learning outcomes using GRI 404 disclosures; embed LCA basics for packaging choices.","Leading":"Institutionalize circular training as a competency framework tied to job families and promotion; run hands-on design sprints using EMF methods; certify advanced roles (e.g., internal “circular packaging lead”) and publish outcomes (projects delivered, % portfolio redesigned)."},"Environmental":{"Awareness":"Adopt an ESD (Education for Sustainable Development) policy for all employees; include core topics in onboarding: resource efficiency, safe and sustainable chemicals, and waste minimization.","Developing":"Integrate periodic (e.g., annual) training modules with case-based scenarios relevant to operations; include supplier-facing staff. Track completion and skills-upgrading per GRI 404; connect content to EMS and eco-design processes.","Leading":"Embed ESD across functions (design, procurement, maintenance) with competency assessments and continuous improvement; publish learning KPIs and link to operational metrics (waste reduction, safe-chemical substitution)."},"Economic":{"Awareness":"Assess current and future skill needs for green and digital transformation (eco-design, LCA, data/automation for material flows). Establish a baseline of training hours and coverage.","Developing":"Fund structured upskilling programs (eco-design via ISO 14006, LCA per ISO 14040/14044; digital skills for take-back/return analytics). Tie learning to process KPIs (line efficiency, defect rates, material yield).","Leading":"Create accredited internal academies and recognized credentials; co-design curricula with unions/partners; publish ROI on training (productivity, waste reductions) under GRI 404-2."},"Social":{"Awareness":"Audit participation in training by gender, age, contract type, migration/disability status where lawful; identify barriers (shift patterns, language, accessibility).","Developing":"Set targeted inclusion measures (paid time for training, accessible formats, language support, mentoring). Track completion and progression by cohort; disclose under GRI 404 and 405.","Leading":"Institutionalize equitable learning pathways (apprenticeships, career ladders) with measurable advancement and pay outcomes; co-create programs with worker reps/ERGs; publish gap-closure targets and progress."}},"SDG_5":{"Circular":{"Awareness":"Assess gender balance in teams working on circular-packaging design, R&D, and operations. Build awareness of women’s contribution to circular innovation and sustainable value-chain management using gender-inclusive design principles.","Developing":"Set measurable gender-participation targets for circular-economy projects; ensure women’s representation in decision-making and technical training (eco-design, recycling systems). Monitor gender balance through GRI 405-1 and report progress annually.","Leading":"Establish mentorship and leadership programs for women in circular innovation roles; integrate gender-responsive design into R&D processes; showcase female-led sustainability solutions publicly."},"Environmental":{"Awareness":"Assess gender-specific risks and participation levels in environmental programs and safety monitoring; build awareness on differentiated exposure to chemicals, waste, and ergonomics.","Developing":"Integrate gender considerations into environmental-management systems (ISO 14001 and ISO 45001); ensure women’s representation in sustainability and resource-efficiency committees; provide training on gender-responsive risk assessment.","Leading":"Adopt a gender-responsive EMS auditing process (ISO 19011); collect sex-disaggregated data on environmental exposures and decisions; communicate outcomes through sustainability reporting and continuous-improvement plans."},"Economic":{"Awareness":"Assess employee needs regarding childcare, eldercare, and work-life balance; communicate the social and economic benefits of family-friendly policies aligned with ILO Convention 156 on Workers with Family Responsibilities.","Developing":"Implement paid parental leave, childcare subsidies, and flexible or remote-work options; monitor participation and satisfaction through HR metrics disclosed in GRI 401-2 (benefits) and GRI 405-2 (pay equality).","Leading":"Institutionalize a comprehensive “care-responsibility” framework combining parental leave, eldercare, and flexible arrangements; evaluate outcomes on retention, productivity, and gender balance; publicly disclose policies and results."},"Social":{"Awareness":"Adopt a zero-tolerance policy on violence and harassment referencing ILO Convention 190; train managers and employees on recognizing and preventing misconduct; communicate available reporting channels.","Developing":"Establish confidential, survivor-centered reporting mechanisms; provide training for grievance officers; monitor case resolution and follow-up actions; disclose system coverage under GRI 406-1 (incidents of discrimination).","Leading":"Integrate anti-harassment measures into enterprise risk and OHS systems; conduct independent audits of policy effectiveness; publish aggregated data and continuous-improvement actions in sustainability reports."}},"SDG_6":{"Circular":{"Awareness":"Assess water inputs and discharge points across packaging production; identify opportunities for reuse and closed-loop treatment systems. Build awareness of circular-water principles using ISO 46001 and EMF’s industrial water-loop case studies.","Developing":"Install water-reuse technologies (filtration, ultrafiltration, RO, condensate recovery); monitor reuse ratios and water savings. Integrate targets into environmental management under ISO 14001 and disclose progress via GRI 303-3 (water recycled and reused).","Leading":"Achieve closed-loop operation for process water; use treated effluents in non-critical production or utilities; publish verified water-recycling performance and innovation results aligned with ISO 46001 and EMF circular-design benchmarks."},"Environmental":{"Awareness":"Map all effluent streams; identify priority pollutants (e.g., inks, coatings, solvents). Build awareness of cleaner-production principles and compliance obligations using UNEP and ISO 14001 frameworks.","Developing":"Introduce cleaner-production technologies (low-VOC inks, water-based coatings); implement in-plant treatment and monitoring; report pollutant reduction under GRI 303-4 and 303-5. Conduct regular compliance audits per ISO 19011.","Leading":"Achieve near-zero liquid discharge or equivalent high-reuse performance; publish water-quality indicators (COD, BOD, heavy metals); partner with suppliers to extend cleaner-production standards throughout the value chain."},"Economic":{"Awareness":"Quantify water consumption costs across facilities; link water-use data to operational expenses. Communicate the financial benefits of efficiency improvements using UN Water and ISO 46001 guidance.","Developing":"Integrate water-efficiency targets into cost-optimization programs; invest in reuse infrastructure; measure payback periods and cost savings. Disclose results in GRI 303 and economic performance sections (GRI 201).","Leading":"Embed water-efficiency metrics in enterprise resource planning (ERP) and ESG dashboards; monetize water savings in sustainability reporting; reinvest savings into further innovation (e.g., smart sensors, AI monitoring)."},"Social":{"Awareness":"Assess water, sanitation, and hygiene (WASH) facilities at all sites; raise awareness of workplace hygiene and its health impacts using WHO/UNICEF WASH guidance.","Developing":"Install safe-drinking-water dispensers and gender-segregated sanitation facilities; provide menstrual-hygiene products and awareness training; verify compliance with WHO water-quality standards and national OHS regulations.","Leading":"Integrate WASH access into corporate-health and wellbeing programs; audit regularly with third-party verification; disclose coverage and improvement actions in sustainability reports and align with SDG 6.2 indicators."}},"SDG_7":{"Circular":{"Awareness":"Map energy flows across production lines to identify waste-heat sources and recovery potential. Build awareness of industrial-symbiosis and energy-loop concepts using ISO 50001 and circular-manufacturing guidance from the Ellen MacArthur Foundation.","Developing":"Install waste-heat recovery (WHR) systems, regenerative burners, or heat-exchanger networks; monitor energy savings and CO₂ reductions. Integrate recovery KPIs within ISO 50001 management reviews and disclose energy-reuse rates in GRI 302-3.","Leading":"Implement fully closed-loop thermal-energy systems or industrial-symbiosis exchanges with nearby facilities; use recovered energy to power ancillary processes. Publicly report avoided-energy consumption and emission savings."},"Environmental":{"Awareness":"Quantify total energy mix and emissions baseline; raise awareness of renewable-energy options and certification schemes (e.g., I-REC, Guarantees of Origin). Link transition goals to corporate climate strategy.","Developing":"Develop a renewable-energy roadmap with clear targets (% of electricity from renewables); implement on-site generation (solar PV, biogas) or long-term PPAs for certified green power. Disclose under GRI 302-1/302-4.","Leading":"Achieve 100 % renewable electricity or net-zero energy operations verified by third-party certification; collaborate with suppliers to extend renewable adoption across the value chain."},"Economic":{"Awareness":"Analyze energy consumption by cost center and identify inefficiencies in machinery, lighting, and compressed-air systems. Communicate potential cost and productivity gains from energy-efficiency investments.","Developing":"Integrate energy-efficiency into capital-planning and maintenance strategies; implement energy audits, high-efficiency motors, and variable-speed drives. Link performance to financial KPIs and disclose ROI and intensity improvements.","Leading":"Institutionalize continual-improvement cycles under ISO 50001; deploy digital-twin or AI systems for predictive optimization; publish verified savings and productivity gains in sustainability and annual reports."},"Social":{"Awareness":"Launch basic energy-awareness campaigns covering conservation behaviors, shutdown procedures, and responsible use of lighting, HVAC, and machinery. Include energy literacy in onboarding.","Developing":"Provide technical training on energy-management practices and renewable-system operation for maintenance, procurement, and engineering teams; measure participation and learning outcomes.","Leading":"Institutionalize ongoing “energy-champion” programs and cross-departmental innovation labs; certify internal experts in ISO 50001; share employee-driven efficiency projects publicly as part of SDG 7 commitments."}},"SDG_8":{"Circular":{"Awareness":"Map packaging/product portfolios to identify reuse/refill/take-back opportunities; assess customer segments and reverse-logistics feasibility; align terminology and principles with ISO 59004 and scan EMF case studies for proven models.","Developing":"Pilot circular models (e.g., B2B totes, refill-on-the-go, deposit-return); define operational specs, cleaning standards, and reverse logistics; measure performance with ISO 59020 metrics and disclose material savings under GRI 301/306.","Leading":"Scale commercially viable reuse/take-back with digital tracking, interoperability, and partner ecosystems; integrate circular revenue lines into strategy and publish verified outcomes (return rates, lifetime turns, avoided waste)."},"Environmental":{"Awareness":"Conduct baseline resource and emissions mapping (energy, materials, water, waste) under ISO 14001; identify hotspots via LCA (ISO 14040/44) and benchmark decoupling potential using UNEP/OECD guidance.","Developing":"Deploy cleaner-production and resource-efficiency technologies (high-efficiency motors/VSDs, heat recovery, low-carbon materials); integrate targets and M&V via ISO 50001/50015; disclose results in GRI 302 (Energy), 303 (Water), 305 (Emissions), 306 (Waste).","Leading":"Institutionalize continuous improvement with eco-design (ISO 14006) and supplier engagement; set science-based, time-bound decoupling targets; verify reductions and publish intensity & absolute metrics."},"Economic":{"Awareness":"Embed sustainability criteria in the innovation pipeline and portfolio governance; align definitions, roles, and processes with ISO 56002 (innovation management) and screen opportunities using LCA and circular-design principles.","Developing":"Stand up stage-gates with environmental KPIs (recyclability, bio-based share, carbon/water intensity); use digital tools (LCA, digital twins, AI for process optimization); report R&D and capability-building under GRI 201/404.","Leading":"Scale market launches that deliver verified sustainability advantages; co-innovate with suppliers/customers; publish revenue share from “sustainable solutions” and third-party-verified impact metrics."},"Social":{"Awareness":"Assess compliance with core labor standards and baseline HR policies (equal pay, non-discrimination, working hours, OSH). Communicate commitments aligned with ILO conventions and GRI disclosures.","Developing":"Implement pay-equity analyses and correction plans; ensure secure contracts and predictable schedules; establish worker participation in OSH per ISO 45001 and provide grievance and remediation channels. Disclose metrics (pay gaps, injury rates, turnover).","Leading":"Set time-bound targets for equal pay and representation at all levels; adopt living-wage roadmaps; integrate inclusive hiring, apprenticeship, and career-progression pathways; independently assure workforce metrics and publish results."}},"SDG_9":{"Circular":{"Awareness":"Identify infrastructure gaps in packaging recovery, sorting, and refill logistics. Map potential synergies with municipalities, industry associations, or recyclers to support circular flows. Align principles with ISO 59004 and Ellen MacArthur Foundation guidance on reuse systems.","Developing":"Co-invest in or co-manage shared collection, cleaning, and refill facilities; establish traceable reverse-logistics partnerships; disclose progress through GRI 301 and 306 indicators.","Leading":"Participate in multi-stakeholder circular infrastructure platforms; develop interoperable refill or deposit-return systems; publicly report system-level material recirculation rates and socio-economic impacts."},"Environmental":{"Awareness":"Assess current infrastructure age, efficiency, and emissions intensity; build understanding of Industry 4.0’s role in energy/resource optimization through ISO 50001 and UNIDO’s industrial modernization guidance.","Developing":"Implement automation, sensor networks, and predictive-maintenance tools to cut energy, water, and material losses; integrate performance data into ISO 14001 environmental-management reviews; disclose progress via GRI 302/305.","Leading":"Adopt fully digital EMS and real-time environmental-performance dashboards; integrate AI optimization; disclose verified resource-efficiency improvements and emission reductions."},"Economic":{"Awareness":"Identify national or regional innovation platforms, clusters, or funding schemes relevant to circular packaging; build awareness of open-innovation benefits using ISO 56002 and UNIDO’s innovation ecosystem resources.","Developing":"Join collaborative R&D or PPP projects; share facilities and data for testing bio-based or recyclable materials; track innovation outputs (patents, prototypes, pilots) and disclose through GRI 203 (Indirect Economic Impacts).","Leading":"Co-lead international innovation consortia; license or scale circular-packaging technologies; publish collaborative R&D outcomes and socio-economic impacts in sustainability reports."},"Social":{"Awareness":"Map supplier diversity and SME engagement in the value chain; communicate the economic and social benefits of inclusive industrial participation referencing ILO and UNIDO guidelines.","Developing":"Implement inclusive-sourcing programs for SMEs, women-owned, or local enterprises; build capacity through supplier training and fair-contracting policies; disclose supplier-diversity metrics in GRI 204-1.","Leading":"Establish long-term partnerships with inclusive suppliers and innovation networks; integrate social-procurement criteria into governance; publish verified socioeconomic impact data and local-employment multipliers."}},"SDG_10":{"Circular":{"Awareness":"Map small and underrepresented actors (SMEs, informal recyclers, social enterprises) in your packaging value chain. Build internal awareness of inclusive-procurement benefits and risks of exclusion in circular economies.","Developing":"Adopt inclusive-sourcing criteria favoring SMEs, cooperatives, and underrepresented suppliers; provide training on quality, safety, and traceability; measure local-spending shares under GRI 204-1.","Leading":"Establish long-term partnerships with inclusive suppliers and circular-economy cooperatives; report verified socio-economic impacts (jobs supported, value retained locally)."},"Environmental":{"Awareness":"Assess employee-engagement structures for inclusiveness (who can make improvement suggestions). Introduce communication channels for all staff to participate in environmental initiatives.","Developing":"Create formal suggestion and review systems (environmental committees, innovation portals, cross-functional “green teams”); guarantee representation from all employee groups and collect data on participation rates.","Leading":"Institutionalize inclusive innovation councils combining environmental, DEI, and OHS functions; publish engagement statistics and environmental-improvement outcomes generated by employee input."},"Economic":{"Awareness":"Audit pay structures and promotion criteria for transparency; benchmark practices against ILO conventions C100 (Equal Remuneration) and C111 (Discrimination).","Developing":"Publish internal pay-band frameworks and promotion policies; provide employees access to performance-evaluation criteria; conduct gender- and diversity-based pay-gap analysis annually.","Leading":"Institutionalize equal-pay certification or external assurance; link bonuses to sustainability and inclusion KPIs; disclose verified pay-equity results and diversity in leadership."},"Social":{"Awareness":"Conduct inclusion-climate surveys; promote cultural-awareness and unconscious-bias training; align internal DEI messaging with the UN Global Compact’s Principle 6 and ILO discrimination conventions.","Developing":"Establish formal DEI programs and employee-resource groups (ERGs); provide mentorship and leadership training for underrepresented groups; measure participation and satisfaction rates under GRI 405.","Leading":"Embed inclusion goals into corporate KPIs; publish annual diversity metrics and inclusion outcomes; obtain external DEI certification or benchmark via recognized indices."}},"SDG_11":{"Circular":{"Awareness":"Map existing municipal or industry-led collection, reuse, and refill initiatives. Identify where company packaging contributes to urban waste streams and raise awareness among staff and partners about extended producer responsibility (EPR).","Developing":"Collaborate with local governments, recyclers, and community enterprises to pilot refill or take-back systems; establish shared data platforms for packaging recovery and reuse tracking.","Leading":"Scale urban reuse and take-back infrastructure through PPPs; co-invest in smart-collection hubs and reverse logistics; publish recovery and reuse metrics under GRI 306."},"Environmental":{"Awareness":"Assess site-level environmental impacts—emissions, dust, odour, and noise—using ISO 14001 and local regulatory standards; raise employee and supplier awareness on urban environmental health.","Developing":"Implement mitigation technologies—low-emission vehicles, particulate filters, acoustic barriers, and waste-heat recovery; monitor progress with GRI 305 and ISO 14031 performance evaluation.","Leading":"Adopt real-time monitoring for air/noise emissions; transition fleet to electric or alternative fuels; publicly disclose verified performance in sustainability reports and ESG indices."},"Economic":{"Awareness":"Identify opportunities for partnerships with micro-enterprises, informal recyclers, and cooperatives bridging urban and rural systems (e.g., bio-based feedstock collection, packaging recovery).","Developing":"Develop inclusive procurement and micro-supply agreements with local cooperatives; provide training, equipment, or logistics support to strengthen their participation in circular material flows.","Leading":"Integrate urban–rural circular partnerships into long-term sourcing and CSR strategy; monitor socioeconomic impact (income growth, waste reduction) and disclose under GRI 203/204."},"Social":{"Awareness":"Assess employees’ commuting, housing, and urban-living challenges; raise awareness of links between mobility, wellbeing, and productivity using ILO and WHO frameworks.","Developing":"Implement flexible or remote work arrangements, commute-support programs (carpooling, public-transit subsidies, bike storage), and urban-safety audits for all sites.","Leading":"Integrate employee urban-wellbeing indicators into sustainability reporting; collaborate with local authorities for safe transport and community infrastructure; disclose progress annually under GRI 401/403."}},"SDG_12":{"Circular":{"Awareness":"Set a baseline for packaging formats and end-of-life pathways; align definitions (reuse, recycling, compostability) with recognized standards and circular principles.","Developing":"Adopt time-bound targets for % reusable, recyclable, or compostable packaging; design to ISO packaging standards, and track diversion under GRI.","Leading":"Scale interoperable reuse/take-back systems with verified outcomes; publish packaging circularity and end-of-life performance."},"Environmental":{"Awareness":"Inventory all chemical inputs across printing/coating/lamination; identify substances of concern; embed responsibilities within the EMS.","Developing":"Implement cleaner-production and substitution procedures; set controls for storage/handling, wastewater pre-treatment, and emission prevention; audit and report.","Leading":"Phase out priority hazardous substances; verify downstream control (e.g., recyclers, contract manufacturers); disclose performance and corrective actions."},"Economic":{"Awareness":"Map material sustainability KPIs to cost drivers (energy, water, materials, waste); establish governance for data quality and decision use.","Developing":"Integrate sustainability KPIs into capital budgeting and management reviews; use MFCA and eco-efficiency to link savings and returns; disclose outcomes.","Leading":"Adopt enterprise-wide dashboards tying resource-efficiency and emissions to P&L and investment decisions; link incentives/bonuses to verified sustainability KPIs."},"Social":{"Awareness":"Define the priority audiences (operators, sales, customers, end-users); align claims and instructions to recognized guidance and avoid greenwashing.","Developing":"Roll out training and customer-facing materials (how to return/reuse/recycle; composting conditions); monitor reach and comprehension; align with packaging end-of-life standards.","Leading":"Co-create community or customer partnerships that measurably improve correct disposal/reuse; publish behavior-change outcomes (return rates, contamination reduction)."}},"SDG_13":{"Circular":{"Awareness":"Map climate-related vulnerabilities in sourcing, manufacturing, logistics, and recycling operations; evaluate exposure to extreme-weather events and resource scarcity.","Developing":"Integrate climate-resilience criteria into supplier selection and circular-design processes; diversify sourcing and build redundancy into reverse-logistics networks.","Leading":"Embed adaptive-capacity KPIs (e.g., supply-chain recovery time, climate-risk scoring) into business continuity; disclose in sustainability and resilience reports."},"Environmental":{"Awareness":"Establish a full GHG inventory (Scopes 1–3) using the GHG Protocol; understand baseline emissions and data-collection processes.","Developing":"Set near- and long-term, science-based GHG-reduction targets; integrate renewable-energy adoption and efficiency upgrades; disclose per GRI 305.","Leading":"Publicly verify inventories and targets via accredited third-party audits; commit to net-zero under recognized frameworks (SBTi Net-Zero Standard)."},"Economic":{"Awareness":"Identify transition and physical risks using TCFD categories; assess exposure and potential financial implications.","Developing":"Integrate TCFD-aligned governance, risk, and opportunity assessments into financial statements; conduct scenario analysis and sensitivity testing.","Leading":"Align financial disclosures with IFRS S2 (ISSB 2023) and TCFD; publish climate-adjusted ROI and internal carbon pricing; embed resilience metrics in corporate finance."},"Social":{"Awareness":"Develop climate-literacy and awareness campaigns for all staff; explain company climate targets and personal relevance.","Developing":"Offer structured internal and supplier-training on energy efficiency, carbon accounting, and adaptation practices; measure learning outcomes and behavioral change.","Leading":"Institutionalize annual climate-competence programs; certify “climate champions”; extend learning to customers and community partnerships; disclose participation metrics."}},"SDG_14":{"Circular":{"Awareness":"Awarenes: Identify potential pathways for plastic or material leakage into water systems; conduct site-level audits of production, transport, and cleaning operations.","Developing":"Implement containment controls (filter traps, sealed storage, stormwater grates, pellet-handling protocols); track and report spills or material losses annually.","Leading":"Certify operations under pellet-loss prevention standards; engage in local watershed cleanups and circular redesign to eliminate leakage risk across the value chain."},"Environmental":{"Awareness":"Awarenes: Map sources of acidifying substances (SO₂, NOₓ, acidic effluents); assess local discharge regulations and downstream water vulnerability.","Developing":"Install treatment systems (neutralization, scrubbers, effluent pH correction); monitor discharge pH and buffer capacity; disclose data through GRI 303.","Leading":"Publicly report pH-adjustment performance and downstream impact studies; collaborate with research bodies on ocean chemistry; aim for zero-acidification footprint."},"Economic":{"Awareness":"Awarenes: Identify research needs regarding aquatic impacts (microplastics, chemical leachates, biodegradability); map external R&D networks and university or NGO partners.","Developing":"Fund or participate in joint R&D projects evaluating biodegradability, toxicity, and water footprint; report findings in ESG disclosures.","Leading":"Co-develop open-access ocean-health databases or biomaterial R&D platforms; disclose funding for marine-research partnerships and eco-design breakthroughs."},"Social":{"Awareness":"Awarenes: Conduct awareness sessions on spill risks, drain mapping, and marine pollution impacts; display clear signage and emergency contacts at operational sites.","Developing":"Establish spill-prevention and stormwater-management procedures; conduct periodic drills; introduce incident-reporting systems and track corrective actions.","Leading":"Integrate spill-prevention and water-protection training into certification programs; publicly disclose incident data and corrective measures; collaborate with coastal NGOs on water quality."}},"SDG_15":{"Circular":{"Awareness":"Awarenwss: Quantify current reliance on virgin vs. recycled/secondary biomass (by mass and spend). Align terminology and targets with circular-economy and chain-of-custody standards; screen feasibility of substituting residues and post-consumer fibers for virgin inputs.","Developing":"Set time-bound targets to increase recycled/secondary content; require chain-of-custody for any remaining virgin inputs; disclose material flows via GRI.","Leading":"Prioritize closed-loop specs with recyclers; publish verified % recycled/secondary content and avoided virgin extraction; integrate circularity metrics into product approvals."},"Environmental":{"Awareness":"Awarenwss: Map all bio-based feedstocks to source regions; identify exposure to deforestation, conversion, and soil-degradation risks; align definitions with the Accountability Framework.","Developing":"Adopt no-deforestation/no-conversion policies; require FSC/PEFC or equivalent certification and ISO 38200/ISO 22095 chain-of-custody; monitor biodiversity impacts and disclose via GRI 304.","Leading":"Ensure alignment with the Kunming–Montreal Global Biodiversity Framework targets; implement supplier due diligence to meet evolving laws (e.g., EUDR) and publish site-level habitat outcomes."},"Economic":{"Awareness":"Awarenwss: Assess nature-related dependencies, impacts, and risks across key commodities; identify potential cost exposures (supply disruption, price volatility, compliance).","Developing":"Integrate TNFD-aligned assessment (LEAP approach) into enterprise risk management; audit suppliers and take actions under GRI 308; set LDN-consistent targets for priority landscapes.","Leading":"Disclose nature-risk governance and metrics (areas at risk, remediation progress, investment in restoration); participate in LDN or landscape-restoration finance mechanisms."},"Social":{"Awareness":"Awarenwss: Develop concise biodiversity & land-use training (site risks, material handling, spill/soil protection); link to corporate commitments (no deforestation/conversion, soil conservation).","Developing":"Roll out role-specific modules (procurement on due diligence, operations on soil/waste handling); track completion and learning outcomes; include biodiversity KPIs in team objectives.","Leading":"Institute annual refreshers and certification for high-impact roles; co-train with suppliers; publicly disclose training coverage and improvements in on-site biodiversity practices."}},"SDG_16":{"Circular":{"Awareness":"Map material flows (virgin, recycled, bio-based) and identify disclosure needs for circular attributes (recyclability, reuse readiness, compostability). Align terminology and approach with circular-economy and chain-of-custody standards.","Developing":"Implement chain-of-custody and product-level data capture (e.g., recycled content, recyclability per ISO 18601–18606); disclose material flows and circular metrics in sustainability reports.","Leading":"Publish audited circularity KPIs (e.g., % recycled/secondary content, % recyclable formats) and use recognized measurement frameworks. Offer clients standardized recyclability and end-of-life information."},"Environmental":{"Awareness":"Establish an environmental management system with defined aspects/impacts, legal registers, and KPIs; set internal reporting cadences.","Developing":"Track and disclose core indicators (energy, water, emissions, waste) using GRI topic standards; assure data quality and governance.","Leading":"Publish externally assured environmental data and targets; provide site-level dashboards where material; align disclosures with recognized frameworks and regulators."},"Economic":{"Awareness":"Adopt a formal anti-corruption policy (incl. gifts, hospitality, COI, third-party risk) and communicate zero tolerance; map high-risk processes (procurement, sales).","Developing":"Implement controls and training per ISO 37001 (anti-bribery); embed sustainable and fair procurement practices and supplier due diligence.","Leading":"Conduct independent compliance audits; disclose incidents and remediation; link leadership incentives to ethics and fair-procurement KPIs."},"Social":{"Awareness":"Assess current channels for participation (surveys, suggestion systems, safety/environment committees) and who is represented; commit to inclusive engagement.","Developing":"Form cross-functional “green & ethics” working groups with elected worker reps; guarantee time and protection for participation; ensure management response and feedback loops.","Leading":"Institutionalize participatory governance (co-chaired sustainability councils, joint improvement charters); disclose participation rates, issues raised, and actions taken."}},"SDG_17":{"Circular":{"Awareness":"Identify local suppliers and recyclers capable of contributing to closed-loop material cycles; assess logistical and economic barriers to local circularity; map regional associations or industrial symbiosis clusters.","Developing":"Form procurement and logistics partnerships to enhance take-back, material recovery, and reuse; co-develop local infrastructure or hubs for circular packaging collection.","Leading":"Co-invest in regional circular innovation ecosystems; publish joint progress reports on local circularity performance (material recovery rates, job creation, emissions reduction)."},"Environmental":{"Awareness":"Review available cleaner-production and eco-design technologies; identify partners for potential technology exchange or licensing aligned with best environmental practices.","Developing":"Engage in bilateral or multi-stakeholder R&D projects on eco-design, recycling, and renewable packaging systems; establish data-sharing agreements and pilot initiatives.","Leading":"Actively share and scale up proven sustainable technologies regionally; contribute to open innovation platforms; co-publish technical outcomes and life-cycle data."},"Economic":{"Awareness":"Identify potential public–private funding programs, EU/UN development finance instruments, or industry consortia supporting circular economy innovation.","Developing":"Collaborate with investors, development agencies, or suppliers to co-fund sustainable packaging R&D or infrastructure; integrate financial metrics into sustainability reporting.","Leading":"Engage in blended-finance consortia or green bonds; publish sustainability-linked investment disclosures; reinvest financial gains into local circular innovation ecosystems."},"Social":{"Awareness":"Identify relevant multi-stakeholder networks and associations (e.g., circular economy hubs, chambers of commerce, packaging councils) and map shared objectives.","Developing":"Participate actively in peer networks, research alliances, or national circular economy platforms; share lessons and co-develop best-practice guidelines.","Leading":"Facilitate regional knowledge-sharing events or open circular data platforms; support local SMEs in capacity-building for sustainable packaging; disclose partnership outcomes."}}}}');

